INSERT INTO `cases` VALUES (35,35,'藍紫嫣','2025-04-11 09:38:58',NULL,'2025-04-11 12:45:55',NULL,'初診','內科','一般門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'午班',NULL,1,NULL,1,NULL,NULL,NULL,NULL,NULL,NULL,'特約門診',NULL,NULL,'特約門診',NULL,NULL,NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'頭皮處紅色斑塊十多年\n患者國中時頭皮處出現小片紅色斑塊,  症狀自己會痊癒. 懷孕後頭皮處紅色斑塊症狀開始愈來愈嚴重, 現在主要分布在, 癢感明顯, 無明顯組織液. 無指甲變形或關節疼痛. 睡眠匹質改善後症狀會改善. 曾用外用類固醇治療, 但停用後症狀又復發而來求診. 生產後週期變正盛, 以前經期較亂. 肚臍皮膚紅斑塊後',NULL,NULL,NULL,'L400','尋常性乾癬','K5900','便秘',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,0,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,0,6150,0,0,0,0,NULL,NULL,0,0,6150,0,100,6150,6150,NULL,NULL,'現金','現金',NULL,'True','False','False','False','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-04-11 04:45:55');
