INSERT INTO `cases` VALUES (30,22,'朱品榕','2025-04-08 11:57:16',NULL,'2025-04-08 12:56:01',NULL,'複診','內科','預約門診',NULL,'自費','普通疾病',NULL,'基層醫療','自費','申報','不申報','免卡',NULL,NULL,'午班',NULL,1,NULL,2,NULL,NULL,NULL,NULL,NULL,NULL,'特約門診',NULL,NULL,'特約門診',NULL,NULL,NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴: 皮膚炎自出生三個月發作\n現病史 皮膚炎自出生三個月發作, 發作於頭部(臉部), 上肢(手肘),  下肢(大腿/膝膕窩/足踝), 軀幹(腹部),  以下之最為嚴重. 局部皮膚紅疹, 色淡紅, 有搔抓傷口, 無組織液滲出, 皮膚粗糙且乾燥. 因癢甚夜眠差, 曾使用西藥類固醇外用, 使用後症狀改善, 現用自調藥膏(左手香/迷迭香/ 薰衣草加橄欖油調製)改善明顯, 但因下肢無明顯改善故來求診.\n鼻塞, 流鼻水, 鼻癢作, 手腕皮膚粗糙\n食物過敏(堅果類/海鮮類)\n胎次2, 自然受孕, 足月, 剖腹產',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,0,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,0,2000,0,0,0,0,NULL,NULL,0,0,2000,0,100,2000,2000,NULL,NULL,'現金','現金',NULL,'True','False','False','False','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-04-08 04:56:01');
