INSERT INTO `cases` VALUES (40,40,'汪培蓉','2025-04-15 17:26:24',NULL,'2025-04-15 18:12:52',NULL,'初診','內科','一般門診',NULL,'自費','普通疾病','99','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'晚班',NULL,1,NULL,1,NULL,NULL,NULL,NULL,NULL,NULL,'特約門診',NULL,NULL,'特約門診',NULL,NULL,NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:雙掌&手指前端&指節間皮膚乾裂以1個月多\n自幼異膚, 皮膚乾裂自去年發作, 上個月惡化, 發作於上肢(手掌/手指前端&指節間), 下肢(小腿), 軀幹(背, 臀部),以雙漲最為嚴重, 局部皮膚乾燥脫屑, 色淡紅, 偶爾發癢, 有搔抓傷口, 無組織液滲出, 皮膚(粗糙/乾燥). 夜眠可, 睡眠中不會搔抓, 不會醒來.曾使用西藥類固醇, 凡士林外用, 口服抗組織胺治療, 使用後癢痛症狀稍有改善, 仍反覆發作. 納可. 大便便祕(2-3日一行,服藥後質軟成形), 小便可. 已停經2-3年, 後腰際皮膚癢.',NULL,NULL,NULL,'L2089','其他異位性皮膚炎','L309','皮膚炎',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,0,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,0,7100,0,0,0,0,NULL,NULL,0,0,7100,0,100,7100,7100,NULL,NULL,'現金','現金',NULL,'True','False','False','False','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-04-15 10:12:52');
INSERT INTO `cases` VALUES (33,23,'辛芃廷','2025-04-09 12:43:18',NULL,'2025-04-09 14:21:16',NULL,'複診','內科','一般門診',NULL,'自費','普通疾病','99','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'午班',NULL,1,NULL,1,NULL,NULL,NULL,NULL,NULL,NULL,'特約門診',NULL,NULL,'特約門診',NULL,NULL,NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴: 濕疹反覆發作\n現病史: 自出生2個月異位性皮膚炎發作, 臉頰兩側紅斑大片, 結痂, 治療層改善, 近復發, 臉, 膕窩, 脖項皮膚炎搔抓嚴重, 眼周, 口周, 皮膚炎有滲液, 睡眠品質不佳, 自上周五下午蕁麻疹發作, 台大治療中, 服西藥, 晨起皮膚膨疹癢作, 下午後緩解, 鼻塞. 手肘, 脖項, 膕窩仍有苔癬化粗厚, 輕微流鼻水, 鼻塞作, 衛教勤擦汗\n自幼異膚, 近臉皮膚炎復發, 滲液',NULL,NULL,NULL,'L209','異位性皮膚炎','J309','過敏性鼻炎',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,0,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,0,708,0,0,0,0,NULL,NULL,0,0,708,0,100,708,708,NULL,NULL,'現金','現金',NULL,'True','False','False','False','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-04-09 07:32:38');
