INSERT INTO `cases` VALUES (84,184,'朱妍蓁','2025-04-30 08:09:14',NULL,'2025-04-30 15:21:13','2025-04-30 17:38:04','初診','內科','一般門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'午班','午班',1,NULL,1,NULL,NULL,NULL,NULL,NULL,NULL,'特約門診',NULL,NULL,'特約門診',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:頭面部皮膚紅斑已十數年\n現病史:十數年前鼻翼兩側乾裂搔癢,反覆未癒。現在頭皮、面部紅斑,搔癢甚,脫屑多。眠差易醒,搔甚。大便平,小便可。2000年乳癌,停經。2018/03/20自行至玉衡中醫治療, 症狀加重, 頭皮膚斑塊厚, 外陰部也有..  \n冬天頭皮癢屑多,頭皮屑厚,鼻側皮膚癢作,手指腹皮乾,指甲生長不良,肛門病灶癢,反胃未改善,',NULL,NULL,NULL,'L400','尋常性乾癬','G4700','非特定的失眠症',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,0,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,0,1150,0,0,0,0,NULL,NULL,0,0,1150,0,100,1150,1150,NULL,NULL,'現金','台灣 Pay',NULL,'True','False','True','False','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-04-30 09:38:04');
