INSERT INTO `cases` VALUES (102,184,'朱妍蓁','2025-05-05 09:22:16',NULL,'2025-05-05 10:48:45',NULL,'複診','內科','一般門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班',NULL,1,NULL,3,NULL,NULL,NULL,NULL,NULL,NULL,'特約門診',NULL,NULL,'李碧涵',NULL,NULL,NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:頭面部皮膚紅斑已十數年\n現病史:十數年前鼻翼兩側乾裂搔癢,反覆未癒。現在頭皮、面部紅斑,搔癢甚,脫屑多。眠差易醒,搔甚。大便平,小便可。2000年乳癌,停經。2018/03/20自行至玉衡中醫治療, 症狀加重, 頭皮膚斑塊厚, 外陰部也有..  \n冬天頭皮癢屑多,頭皮屑厚,鼻側皮膚癢作,手指腹皮乾,指甲生長不良,肛門病灶癢,反胃未改善, 用',NULL,NULL,NULL,'L400','尋常性乾癬','G4700','非特定的失眠症',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,0,400,0,0,0,0,NULL,NULL,0,0,400,0,100,400,400,NULL,NULL,'現金','現金',NULL,'True','False','False','False','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-05-05 02:48:45');
INSERT INTO `cases` VALUES (105,14,'江晨浩','2025-05-05 10:17:14',NULL,'2025-05-05 10:37:48',NULL,'複診','內科','預約門診',NULL,'自費','普通疾病','99','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班',NULL,1,NULL,2,NULL,NULL,NULL,NULL,NULL,NULL,'特約門診',NULL,NULL,'李碧涵',NULL,NULL,NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'身上多處紅疹\n皮膚炎自出生4個月發作, 發作於頭部, 臉部, 頸部, 手肘,大小腿/膝膕窩/足踝, 胸腹部, 皮膚紅腫/紅疹, 皮膚粗糙/乾燥, 因癢甚, 夜眠差. 曾使用西醫組織胺治療, 停藥後症狀又復發. 納可, 二便平. 臀部皮膚紅疹塊',NULL,NULL,NULL,'L209','異位性皮膚炎',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'預約報到過號',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,0,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,0,2580,0,0,0,0,NULL,NULL,0,0,2580,0,100,2580,2580,NULL,NULL,'現金','現金',NULL,'True','False','False','False','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-05-05 03:18:40');
INSERT INTO `cases` VALUES (108,19,'呂芳琦','2025-05-05 16:52:43',NULL,'2025-05-05 19:48:59','2025-05-05 20:47:08','複診','內科','一般門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'晚班','晚班',1,NULL,11,NULL,NULL,NULL,NULL,NULL,NULL,'特約門診',NULL,NULL,'特約門診',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴: 頭皮, 背部, 肘外手臂外側呈暗紅色搔癢性斑塊伴有鱗屑, 雙手皮增厚, 手指背側脫屑\n現病史: 47歲乾癬發作, 曾於皮膚科就診, 使用類固醇藥膏及口服抗組織胺未效. 目前病灶出現於頭皮, 背部, 肘外手臂外側呈紅案紅色斑塊伴有鱗屑, 搔癢, 夜間尤甚, 影響入睡. 雙手掌膚增厚, 手指背側脫屑. 食納平,  大便; \n\n乾癬病灶變化大有新長紅疹多, 手臂皮膚病灶紅斑塊乾而有屑, 頭皮膚癢 斑塊厚, 鱗屑厚少, 高血壓併服西藥, 控制可 SBP 120 mmHg衛教飲食',NULL,NULL,NULL,'L400','尋常性乾癬','I10','本態性(原發性)高血壓',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,0,2600,0,0,0,0,NULL,NULL,0,0,2600,0,100,2600,2600,NULL,NULL,'現金','現金',NULL,'True','False','True','False','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-05-05 12:47:08');
