INSERT INTO `cases` VALUES (192,27,'徐若婷','2025-05-26 14:19:11',NULL,'2025-05-26 15:18:15',NULL,'複診','內科','一般門診',NULL,'自費','普通疾病','99','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'午班',NULL,1,NULL,38,NULL,NULL,NULL,NULL,NULL,NULL,'特約門診',NULL,NULL,'鄭雪菁',NULL,NULL,NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'271211\n主訴: 四肢, 腰背牽連臀部泛發紅色搔癢丘疹超過五週\n現病史: 五週前四肢, 腰背牽連臀部突發性紅色搔癢丘疹, 無明確誘發因子/加重因子, 現病灶於四肢/手腳掌/手指腳趾與腰背/臀部, 以膝蓋最甚, 丘疹色紅且搔癢, 搔抓出血且滲組織液, 偶脫屑. 西醫診斷為濕疹, 塗抹類固醇可改善, 停藥後復發, 因癢甚影響睡眠. \n食慾可, 大便一天一行, 羊屎便, 小便可\n250407 脖頸皮膚紅疹, 丘疹',NULL,NULL,NULL,'L209','異位性皮膚炎',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,0,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,8110,0,0,0,0,NULL,NULL,0,0,8410,0,100,8410,8410,NULL,NULL,'現金','現金',NULL,'True','False','False','False','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-05-26 07:18:15');
