INSERT INTO `cases` VALUES (202,848,'薛晴安','2025-05-27 15:12:53',NULL,'2025-05-27 15:27:36',NULL,'初診','內科','一般門診',NULL,'自費','普通疾病','99','三歲兒童','自費','申報','不申報','免卡',NULL,NULL,'午班',NULL,1,NULL,11,NULL,NULL,NULL,NULL,NULL,NULL,'特約門診',NULL,NULL,'李碧涵',NULL,NULL,NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:皮膚搔癢自出生2個月發作\n現病史:皮膚炎自出生2個月發作,發作於臉部、耳後、頭部、上肢(手肘)、下肢(膝膕窩)、軀幹(腰背部右臀部、會陰),以臉部最為嚴重。局部皮膚红疹,色红,有搔抓滲出,皮膚乾燥,因癢甚夜眠差,睡眠中不自覺搔抓、不會醒來。曾使用西醫類固醇外用、口服抗組織胺和類固醇治療,鼻涕使用後症狀有改善,皮膚症狀有些微改善',NULL,NULL,NULL,'L209','異位性皮膚炎',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,0,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,0,12160,0,0,0,0,NULL,NULL,0,0,12160,0,100,12160,12160,NULL,NULL,'現金','現金',NULL,'True','False','False','False','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-05-27 07:29:14');
