INSERT INTO `cases` VALUES (200,899,'彭依寒','2025-05-27 14:07:36',NULL,'2025-05-27 14:48:46',NULL,'初診','內科','一般門診',NULL,'自費','普通疾病',NULL,'基層醫療','自費','申報','不申報','免卡',NULL,NULL,'午班',NULL,1,NULL,7,NULL,NULL,NULL,NULL,NULL,NULL,'特約門診',NULL,NULL,'李碧涵',NULL,NULL,NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'腳踝, 腳趾皮膚炎紅腫, \n手肘, 手腕皮膚炎搔抓紅疹, ',NULL,NULL,NULL,'L309','皮膚炎',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,0,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,0,3430,0,0,0,0,NULL,NULL,0,0,3430,0,100,3430,3430,NULL,NULL,'現金','現金',NULL,'True','False','False','False','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-05-27 06:48:46');
INSERT INTO `cases` VALUES (201,858,'楊宜潔','2025-05-27 15:00:05',NULL,'2025-05-27 15:11:53',NULL,'初診','內科','一般門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'午班',NULL,1,NULL,9,NULL,NULL,NULL,NULL,NULL,NULL,'特約門診',NULL,NULL,'李碧涵',NULL,NULL,NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'#主訴:四肢及頭皮紅斑塊2年\n現病史:患者兩年前工作壓力大 掉髮多 發現頭皮红斑塊,皮膚科診斷乾癬 接受外用類固醇及抗组織胺治療,但仍反覆發作,曾接受中藥洽療但無改善。目前四肢有1*1公分斑塊數塊 色淡紅 伴輕微脫屑 無凸起 癢,頭皮有7*8公分斑塊 微凸起 鱗屑厚 。無指甲異常 關節無疼痛。天氣變化時易打噴嚏流鼻水 睡覺時易鼻塞 眼睛癢鼻癢。LMP:5/12經痛一日,3-4日量多伴血塊 經期結束前頭痛。眠可(11點入睡)偶失眠。二便平。胃易脹氣喝牛奶及豆漿時加重。每日一杯咖啡,治療後膚紅斑塊改善,鼻塞改善,\n2025/05/27 服中藥,易口乾,稍有減輕,皮膚乾燥作乾眼症,難經治療,仍乾澀,眼周皮膚乾燥,夜間乾醒,點藥油會,胃脹氣作,',NULL,NULL,NULL,'L409','乾癬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,0,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,0,460,0,0,0,0,NULL,NULL,0,0,460,0,100,460,460,NULL,NULL,'現金','現金',NULL,'True','False','False','False','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-05-27 07:11:53');
INSERT INTO `cases` VALUES (204,55,'陳宥愷','2025-05-28 14:57:23',NULL,'2025-05-28 15:13:52',NULL,'複診','內科','預約門診',NULL,'自費','普通疾病','99','三歲兒童','自費','不申報','不申報','G000',NULL,NULL,'午班',NULL,1,NULL,14,NULL,NULL,NULL,NULL,NULL,NULL,'特約門診',NULL,NULL,'李碧涵',NULL,NULL,NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:全身皮膚泛紅乾燥\n現病史: 全身皮膚泛紅癢自出生二個月作, 臉皮膚紅\n腿皮膚癢作, 乾燥搔抓, 臉泛紅疹, 尿布疹癢',NULL,NULL,NULL,'L2089','其他異位性皮膚炎',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,0,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,6900,0,0,0,0,NULL,NULL,0,0,7200,0,100,7200,7200,NULL,NULL,'現金','現金',NULL,'True','False','False','False','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>2</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-05-28 07:28:45');
INSERT INTO `cases` VALUES (205,415,'連志文','2025-05-28 15:31:28',NULL,'2025-05-28 15:39:26',NULL,'複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'午班',NULL,1,NULL,20,NULL,NULL,2,NULL,NULL,NULL,'特約門診',NULL,NULL,'李碧涵',NULL,NULL,NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:頭皮膚乾癬作\n現病史:病患自30年前皮膚開始長出紅斑,頭皮,臉,手臂,大腿,小腿,膝,皆有紅色斑塊,屑,很癢,關節疼痛,2013曾至本院治療,\n近頭皮膚乾作病灶紅斑脫屑癢嚴重,影響到睡眠,臉,手臂,大腿,小腿,膝皆有紅色斑塊,無關節疼痛指甲光滑平整 冬天乾燥時較嚴重 氣溫上升後較緩和 眠差 過敏性鼻炎晚上鼻塞嚴重 白天口渴 多汗,二便平\n2025/05/28 手臂,大腿,小腿,膝皮膚有紅色斑塊,減輕,仍睡不好,鼻塞,夜咳作 未改善,,',NULL,NULL,NULL,'L400','尋常性乾癬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'預約報到過號',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,0,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,0,1320,0,0,0,0,NULL,NULL,0,0,1320,0,100,1320,1320,NULL,NULL,'現金','現金',NULL,'True','False','False','False','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-05-28 07:39:26');
