INSERT INTO `cases` VALUES (256,81,'謝曉惠','2025-06-05 16:01:23',NULL,'2025-06-05 16:24:53','2025-06-05 17:36:49','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'晚班','晚班',1,NULL,2,NULL,NULL,3,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'鄭雪菁',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:手掌腳掌紅斑塊8年塊七年\n現病史:病患自13歲開始出現雙手指甲變形脫落,三年前開始雙手手掌及腳掌出現紅斑塊。月經前開始長黃色小包,乾掉破裂後恢復光滑皮膚,周期約一個月。曾於西醫皮膚科接受MTX治療一個月,但紅斑變多故停藥。目前手掌、手背關節處及腳踝腳掌皮紅斑塊遍布有膿泡,BSA>5%,鱗屑多厚。12歲初經,月經週期28-30天,持續五天、色紅血塊少,無經前不適、月經來時伴輕微頭痛及乳房脹痛。眠可(12:30-8:00)。大便一日一行,成形條狀。小便平。無關節痛。口乾口渴,目前LMD皮膚科擦藥膏\n左手指前側膿包己減少,但斑塊仍厚,指甲膿包反復',NULL,NULL,NULL,'L403','掌蹠膿疱症',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,0,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,5608,0,0,0,0,NULL,NULL,0,0,5908,0,100,5908,5908,NULL,NULL,'現金','現金',NULL,'True','False','True','True','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-06-05 09:36:50');
