INSERT INTO `cases` VALUES (262,431,'許芷晴','2025-06-05 17:51:18',NULL,'2025-06-05 18:08:32','2025-06-05 18:20:43','複診','內科','預約門診',NULL,'自費','普通疾病','99','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'晚班','晚班',1,NULL,16,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'鄭雪菁',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'\n2020/08/06\n主訴:全身丘疹散布;項後、雙肘屈側、雙踝外側乾燥疹塊 约3個月\n現病史:乾燥性疹塊自出生8個月發作於全身(臉頰無),塗乳液。109/5雙頰紅疹,皮膚科外用類固醇藥膏改善,之後胸背病毒疹發作治療後,全身紅癢疹作未治療。\n目前全身紅疹散布,腿後側粗糙,項後、雙肘屈側、雙踝外側乾燥疹塊,搔嚴重影響睡眠,搔抓後組織液滲出,偶有流血。後項、踝搔抓最嚴重。頭皮脫屑。納可。二便平。',NULL,NULL,NULL,'L209','異位性皮膚炎',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'免',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,0,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,4590,0,0,0,0,NULL,NULL,0,0,4890,0,100,4890,4890,NULL,NULL,'現金','現金',NULL,'True','False','True','False','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-06-05 10:20:44');
