INSERT INTO `cases` VALUES (368,153,'陳燦','2025-06-11 10:33:46',NULL,'2025-06-11 10:49:33','2025-06-11 10:49:33','複診','內科','預約門診',NULL,'自費','普通疾病','99','三歲兒童','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,36,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:臉皮膚紅疹\n現病史:臉頰紅疹,搔抓,脖頸皮膚红\n近頭皮膚搔抓 臉红疹仍有多,红腫,腹部皮膚 有粗疹厚,腰腹搔抓,臉皮膚紅腫傷口 搔抓減少,,頭皮紅疹,頭皮胎垢 厚減輕, 腿皮膚微乾, 腹側皮膚粗疹\n2025/05/24 下雨天, 皮膚炎惡化, 現臉皮膚紅腫\n2025/06/11 右臉改善, 左臉眼下搔抓傷口紅, 手肘改善',NULL,NULL,NULL,'L2089','其他異位性皮膚炎','L239','過敏性接觸性皮膚炎，未明示原因',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'預約報到過號',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,9700,0,0,0,0,NULL,NULL,0,0,10000,0,100,10000,10000,NULL,NULL,'現金','現金',NULL,'True','False','True','True','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-06-11 06:05:41');
