INSERT INTO `cases` VALUES (443,657,'^曾怡璁','2025-06-16 17:56:41',NULL,'2025-06-16 18:02:47','2025-06-16 18:02:47','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'晚班','晚班',1,NULL,3,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'范詩豔',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'2017/08/22\n主訴:皮膚紅色斑塊约1年\n現病史:皮膚紅色斑塊约1年。主要位於頭皮。色淡紅增厚,脫屑,不規則形,會搔癢。指甲無影響,關節無影響。曾使用西醫藥膏類固醇治療,但效果平。納可,二便可,眠可。偶發膨疹\n2025/06/16 頭皮多,額皮膚乾癬斑塊新長,腿皮膚斑塊厚,',NULL,NULL,NULL,'L400','尋常性乾癬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'報稅',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,1820,0,0,0,0,NULL,NULL,0,0,2120,0,100,2120,2120,NULL,NULL,'現金','現金',NULL,'True','False','True','False','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-06-16 11:59:32');
INSERT INTO `cases` VALUES (444,28,'^黃宥均','2025-06-16 17:59:27',NULL,'2025-06-16 18:14:08','2025-06-16 18:14:08','複診','內科','預約門診',NULL,'自費','普通疾病','99','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'晚班','晚班',1,NULL,2,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'范詩豔',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:全身起紅疹約7年\n現病史:自一歲起發作, 兩年前症狀最嚴重, 有看本院皮膚科, 擦類固醇藥膏,  服用中醫診所的中藥, 癢甚時服用抗組織胺, 現分布於頭皮, 耳後, 臉頰, 四肢皮膚粗糙乾燥脫屑有搔抓傷口, 影響睡眠故眠差, 納差, 二便可\n250123 臉皮膚脫皮',NULL,'報稅',NULL,'L209','異位性皮膚炎',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'預約報到過號',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,4920,0,0,0,0,NULL,NULL,0,0,5220,0,100,5220,5220,NULL,NULL,'現金','現金',NULL,'True','False','True','False','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-06-16 11:58:42');
