INSERT INTO `cases` VALUES (481,31,'丁士宗','2025-06-19 17:41:49',NULL,'2025-06-19 17:52:18','2025-06-19 17:52:18','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'晚班','晚班',1,NULL,28,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:皮膚紅斑塊約八年\n現病史:35歲起頭皮紅斑塊, 曾接受西醫類固醇治療有改善, 停藥後反覆發作, 無照光或內服藥治療. 目前皮膚病灶分布於手掌, 手背, 雙臂上側, 小腿, 大退內側大片; 抓出血結紅痂, 伴有鱗屑, BSA 15%, 手指甲點狀凹陷四五年, 目前服抗憂鬱藥物(憂鬱症輕症), 目前工作壓力尚可, 睡眠可, 食慾可, 無胃脹氣不適感, 大便平, 鼻過敏症狀, 無胃食道逆流, 有脂肪肝\n後頸, 皮膚斑塊改善又作',NULL,NULL,NULL,'L409','乾癬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'報稅',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,5400,0,0,0,0,NULL,NULL,0,0,5700,0,100,5700,5700,NULL,NULL,'現金','現金',NULL,'True','False','True','True','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-06-19 11:39:21');
