INSERT INTO `cases` VALUES (534,847,'洪依雯','2025-06-21 10:46:22',NULL,'2025-06-21 11:38:57','2025-06-21 11:38:57','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,44,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:皮膚紅斑塊自國中發作\n現病史:皮膚紅斑塊自國中發作,目前全身紅斑塊遍布,BSA>5%,腹部和後背病灶較大片四肢零星皮膚癢不易睡\n2025/05/13 在日本惡化乾癬,現四肢,臀部零星红斑塊,便秘服藥腹瀉,,合併西藥外用',NULL,NULL,NULL,'L409','乾癬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'免',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,2100,0,0,0,0,NULL,NULL,0,0,2400,0,100,2400,2400,NULL,NULL,'現金','現金',NULL,'True','False','True','True','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-06-21 03:47:20');
INSERT INTO `cases` VALUES (535,565,'^蘇慶祥','2025-06-21 11:05:39',NULL,'2025-06-21 11:42:23','2025-06-21 11:42:23','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,45,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'2019/02/12\n主訴:全身皮膚紅色斑塊伴隨鱗屑約12年\n現病史:乾癬發作於25歲,曾於皮膚科就診,使用類固醇藥膏可改善。目前乾癬發作於四肢伸側、面頸及腰背部,伴有鱗屑,搔癢感甚,不影響睡眠。\n入睡困難,夢多。食納平,食後腹脹,夜間乾咳,口乾渴,飲不止渴。大便日1行,小便平。\n2025/05/17 睡不好改善,',NULL,NULL,NULL,'L400','尋常性乾癬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'報稅',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,5600,0,0,0,0,NULL,NULL,0,0,5900,0,100,5900,5900,NULL,NULL,'現金','現金',NULL,'True','False','True','True','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-06-21 05:20:57');
