INSERT INTO `cases` VALUES (542,1154,'鄭雪菁','2025-06-21 12:53:06',NULL,'2025-06-21 12:58:35','2025-06-21 12:58:35','複診','內科','預約門診',NULL,'自費','普通疾病','67','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,54,NULL,NULL,14,NULL,NULL,NULL,'林胤谷',NULL,NULL,'林胤谷',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'潮熱, 盜汗,眠差, 胃脹氣,',NULL,NULL,NULL,'N951','停經及女性更年期之病況','G4709','其他失眠症',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'預約報到過號',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,0,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,0,1449,0,0,0,0,NULL,NULL,0,0,1449,0,100,400,400,NULL,NULL,'現金','現金',NULL,'True','False','True','False','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-06-21 10:59:00');
INSERT INTO `cases` VALUES (543,91,'李仁富','2025-06-23 14:51:07',NULL,'2025-06-23 15:08:25','2025-06-23 15:08:25','複診','內科','預約門診',NULL,'自費','普通疾病',NULL,'基層醫療','自費','申報','不申報','免卡',NULL,NULL,'午班','晚班',1,NULL,1,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'范詩豔',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:右腳底起疹癢甚约十年\n現病史:自當兵起右腳開始起疹癢甚,一年约會有1.2次特別嚴重特別癢,上個月有看西醫皮科,擦類固醇藥膏和服用抗组織胺治療,現已停藥,眠可,納可,排便一日2-3次偏軟。疹只零星分佈於右腳腳底,局部稍粗糙乾燥,有脫屑,天熱不一定會加重。偶起小水泡。\n250331 飲食控制,穩定無水泡作',NULL,NULL,NULL,'L249','刺激性接觸性皮膚炎，未明示原因',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'免',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,2640,0,0,0,0,NULL,NULL,0,0,2940,0,100,2940,2940,NULL,NULL,'現金','現金',NULL,'True','False','True','False','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-06-23 07:30:29');
INSERT INTO `cases` VALUES (544,92,'李安晨','2025-06-23 14:51:19',NULL,'2025-06-23 15:10:45','2025-06-23 15:10:45','複診','內科','預約門診',NULL,'自費','普通疾病','99','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'午班','晚班',1,NULL,2,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'范詩豔',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:全身多處紅色疹數月\n現病史:皮膚炎自出生3個月發作,起先症狀較輕。昨天開始因為不明原因全身發作紅疹塊,發作於頭部(臉部/頭皮/耳後)、頭部、上肢(手肘/手腕)、下肢(大小腿/膝膕窩/足踝)、軀幹(胸/腹部/腰背部)。局部皮膚紅腫伴隨紅疹,色鲜红,無搔抓傷口,脖子有組織液滲出,皮膚(粗糙、乾燥)。夜眠可,睡眠中不自覺搔抓、醒來會抓得更厲害。曾使用西醫類固醇外用,使用後症狀改善,停藥後症狀又復發。納可。二便平。\n250331 飲食不節 皮膚乾燥,搔抓,流鼻水改善,國窩搔抓\n膕窩皮膚炎搔抓, ',NULL,NULL,NULL,'L209','異位性皮膚炎','J309','過敏性鼻炎',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'免',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,7520,0,0,0,0,NULL,NULL,0,0,7820,0,100,7820,7820,NULL,NULL,'現金','現金',NULL,'True','False','True','False','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-06-23 07:10:45');
