INSERT INTO `cases` VALUES (549,567,'何明欽','2025-06-23 16:12:41',NULL,'2025-06-23 16:37:36','2025-06-23 16:37:36','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'晚班','晚班',1,NULL,7,NULL,NULL,2,NULL,NULL,NULL,'林胤谷',NULL,NULL,'范詩豔',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:後背皮膚紅斑塊遍布,\n現病史:乾癬發作二年,目前全身零星分布,BSA>5%,晨起口苦減輕,小腿和後背 紅疹塊持平\n2025/05/17 後腰臀病灶仍厚,癢偶作,偶擦西藥\n2025/06/23 手臂紅斑塊零星, ',NULL,NULL,NULL,'L409','乾癬','K279','消化性潰瘍，部位未明示，未明示急性或慢性，未伴有出血或穿孔',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,3487,0,0,0,0,NULL,NULL,0,0,3787,0,100,3780,3780,NULL,NULL,'現金','現金',NULL,'True','False','True','False','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-06-23 08:37:36');
INSERT INTO `cases` VALUES (550,542,'楊忠敏','2025-06-23 16:17:56',NULL,'2025-06-23 16:45:59','2025-06-23 16:45:59','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'晚班','晚班',1,NULL,8,NULL,NULL,3,NULL,NULL,NULL,'林胤谷',NULL,NULL,'范詩豔',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'@主訴 : 後背和大腿紅斑塊多 ,\n現病史:十年前始發開始 後腦勺局部一小塊乾癬之後範圍擴大至全頭皮 反覆發作,之後手肘、小腿後側,膝蓋也發出病灶,紅色斑塊,局部粗糙增厚,有多處抓傷口,2018年才開始延伸至軀幹、腰背部大片紅疹,病情反覆,跑過多家醫院診所(黃.憲等),藥膏(Xamiol),未曾口服西藥,只有口服中藥,但停藥皆復發。誤認磨去死皮再擦藥吸收效果佳。\n2025/06/23 中,左手臂手肘病灶厚 改善緩慢,',NULL,NULL,NULL,'L400','尋常性乾癬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'免',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,3858,0,0,0,0,NULL,NULL,0,0,4158,0,100,4150,4150,NULL,NULL,'現金','現金',NULL,'True','False','True','False','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-06-28 08:37:57');
