INSERT INTO `cases` VALUES (553,480,'黎丞軒','2025-06-23 17:26:54',NULL,'2025-06-23 17:28:58','2025-06-23 17:28:58','複診','內科','預約門診',NULL,'自費','普通疾病','99','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'晚班','晚班',1,NULL,11,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'范詩豔',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'@2021/08/12\n主訴:前、四肢屈側红疹零星3個月\n現病史:皮膚炎自出生2個月發作臉部,於小兒科外用類固醇,但症狀反覆,天熱加劇。\n目前紅疹位於胸前、四肢屈側、後頭部,全身皮膚粗糙感。納可。二便平。\n2025/06/23 大腿皮膚內側搔抓癢疹,手臂癢,',NULL,NULL,NULL,'L209','異位性皮膚炎',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'預約報到過號',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,1500,0,0,0,0,NULL,NULL,0,0,1800,0,100,1800,1800,NULL,NULL,'現金','現金',NULL,'True','False','True','False','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-06-28 08:38:36');
