INSERT INTO `cases` VALUES (558,540,'黃美娟','2025-06-24 08:14:21',NULL,'2025-06-24 08:21:17','2025-06-24 08:21:17','複診','內科','一般門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,5,NULL,NULL,1,NULL,NULL,NULL,'林胤谷',NULL,NULL,'游惠玲',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'2017.03.20\n主 訴 :乾癬復發\n現病史:皮膚紅色斑塊約10多年。位於手臂、大腿小腿、腰背部。BSA2.5%。色淡红,增厚,脫屑,圓形,不會搔癢。2017/03/20 PASI:3.5 BSA:1.3% 本治療改善,近飲食不節又作,頭皮屑多,頭皮紅斑塊,,四肢皮膚紅斑塊,耳內,皮下出血,\n2025/05/13 指甲乾癬近惡化,手掌皮膚乾燥持續改善,頭皮紅斑塊改善,頭皮頭髮有新長,後項皮膚乾癬癢,紅疹,後背 腿皮紅斑塊 減輕中,頭皮屑多減少,四肢皮膚紅斑塊減少\n内有屑少,',NULL,NULL,NULL,'L409','乾癬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,240,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,2664,0,0,0,0,NULL,NULL,0,0,2964,0,100,2960,2960,NULL,NULL,'現金','現金',NULL,'True','False','True','True','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-06-24 00:25:50');
INSERT INTO `cases` VALUES (559,251,'柯沂孜','2025-06-24 08:24:01',NULL,'2025-06-24 08:40:19','2025-06-24 08:40:19','複診','內科','一般門診',NULL,'自費','普通疾病','82','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,13,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'游惠玲',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:頭皮搔抓\n現病史:頭皮膚搔抓,有疹,手肘,膝,腳踝搔抓有疹,耳裂\n2025/05/06 膕窩皮膚病灶乾粗,苔蘚化仍有,運動流汗皮膚癢易作,手肘內,膕窩發炎,咳嗽痰多,流鼻水改善,胸前搔抓有疹大腿後疹 頭皮癢有屑,手腕,手背皮膚疹改善,, 偶有鼻血已無',NULL,NULL,NULL,'J300','血管舒縮性鼻炎',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'T',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,8900,0,0,0,0,NULL,NULL,0,0,9200,0,100,9200,9200,NULL,NULL,'現金','現金',NULL,'True','False','True','True','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-06-24 00:43:46');
INSERT INTO `cases` VALUES (560,177,'張宸菲','2025-06-24 08:24:54',NULL,'2025-06-24 08:55:57','2025-06-24 08:55:57','複診','內科','一般門診',NULL,'自費','普通疾病','99','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,15,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'游惠玲',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'2019/02/19\n主訴:雙臉頰、腿外側皮膚炎2個月\n現病史:皮膚炎自出生2個月發作,發作於頭部(臉部/頭皮)、上肢手臂、下肢小腿、驅幹(胸腹部/腰背部),以臉及小腿外側最為嚴重 二便平一天一兩行。  身側腰際,皮膚乾燥,粗疹反覆,流鼻水晨作,打噴嚏,偶發\n2025/.06/24 身側腰際,皮膚乾燥,粗疹反覆,流鼻水晨作,打噴嚏,偶發',NULL,NULL,NULL,'L209','異位性皮膚炎',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'X',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,4400,0,0,0,0,NULL,NULL,0,0,4700,0,100,4700,4700,NULL,NULL,'現金','現金',NULL,'True','False','True','True','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-06-24 01:35:58');
INSERT INTO `cases` VALUES (561,51,'俞建宏','2025-06-24 08:51:29',NULL,'2025-06-24 09:04:13','2025-06-24 09:04:13','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,16,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'游惠玲',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:全身多處紅斑塊20年\n現病史:患者20年前因為不明原因頭皮處出現紅色斑塊, 之後陸陸續續全身, 四肢, 臉部都出現紅色斑塊, 病灶處增厚起; 乾癬持平, 皮膚乾燥, 後輩皮膚紅斑塊鱗屑厚, 大片, 乾燥, 癢作, 衛教運動, 注意飲食, 不規則服藥',NULL,NULL,NULL,'L409','乾癬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'預約報到過號',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,4000,0,0,0,0,NULL,NULL,0,0,4300,0,100,4300,4300,NULL,NULL,'現金','現金',NULL,'True','False','True','True','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-06-24 01:36:00');
