INSERT INTO `cases` VALUES (579,858,'楊宜潔','2025-06-24 11:03:56',NULL,'2025-06-24 12:08:31','2025-06-24 12:08:31','複診','內科','一般門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,38,NULL,NULL,10,NULL,NULL,NULL,'林胤谷',NULL,NULL,'游惠玲',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'#主訴:四肢及頭皮紅斑塊2年\n現病史:患者兩年前工作壓力大 掉髮多 發現頭皮红斑塊,皮膚科診斷乾癬  目前四肢有1*1公分斑塊數塊 色淡紅 伴輕微脫屑 無凸起 癢,頭皮有7*8公分斑塊 微凸起 鱗屑厚 。 。天氣變化時易打噴嚏流鼻水 睡覺時易鼻塞 眼睛癢鼻癢。 。眠可(11點入睡)偶失眠。 。胃易脹氣喝牛奶及豆漿時加重。每日一杯咖啡,治療後膚紅斑塊改善,鼻塞改善,\n2025/05/27 服中藥,易口乾,稍有減輕,皮膚乾燥作乾眼症,難經治療,仍乾澀,眼周皮膚乾燥,夜間乾醒,點藥油會,胃脹氣作,\n2025/06/24 角膜破皮,  外感後, 皮膚乾燥, 流汗多,',NULL,NULL,NULL,'L409','乾癬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,1200,0,0,0,0,NULL,NULL,0,0,1500,0,100,1500,1500,NULL,NULL,'現金','現金',NULL,'True','False','True','True','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-06-24 04:30:54');
