INSERT INTO `cases` VALUES (618,716,'王錫燕','2025-06-26 17:42:59',NULL,'2025-06-26 18:18:01','2025-06-26 18:18:01','複診','內科','預約門診',NULL,'自費','普通疾病','67','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'晚班','晚班',1,NULL,27,NULL,NULL,4,NULL,NULL,NULL,'林胤谷',NULL,NULL,'李碧涵',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'2020/07/16\n主訴:臉部皮膚眉上及鼻樑、頭皮搔癢2年\n現病史:4-5年前當義工忙碌後右下肢開始出現點狀紅色斑塊,近2年頭皮、臉部眉上及鼻樑、胸部有點狀紅色斑塊,搔癢脫屑,至皮膚科診所診斷為乾癬,目前規律回診,服藥後紅色斑塊消退,無脫屑,搔癢感仍有,頭皮處搔癢嚴重,流汗後頭皮、眉上及鼻樑易出現紅色點狀斑塊、搔癢加重,因搔癢感淺眠易醒,大便一日1-2行,質軟,小便可。\n2025/05/22 天熱皮膚癢,乾燥搔抓作,頭皮癢 臉部 手掌皮膚 紅疹,癢,  手臂,腿皮膚紅疹新長,癢作  臉,脖頸,皮膚紅癢疹偶作 癢感夜間,流鼻水,打噴嚏近少作,\n額有痤瘡大顆改善,後枕斑塊厚減輕,腿皮膚乾粗,減輕,躁熱作稍減,天冷皮膚乾燥發癢作,衛教洗澡方式有改善',NULL,NULL,NULL,'L239','過敏性接觸性皮膚炎，未明示原因','N951','停經及女性更年期之病況',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'X',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,1176,0,0,0,0,NULL,NULL,0,0,1476,0,100,1470,1470,NULL,NULL,'現金','現金',NULL,'True','False','True','True','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-06-26 11:03:39');
