INSERT INTO `cases` VALUES (638,589,'廖晨妍','2025-06-27 09:55:04',NULL,'2025-06-27 10:08:57','2025-06-27 10:08:57','複診','內科','預約門診',NULL,'自費','普通疾病',NULL,'基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,20,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'2024/08/07\n主訴:皮膚癢疹反復十多年\n現病史:自幼皮膚癢疹作,腰際皮膚搔抓紅疹較嚴重,四肢零星,起床流鼻水,飲食衛教,衣著不要太緊\n 小腿皮膚搔抓傷口有結痂厚黃改善 但仍有疹塊,手臂皮膚搔抓疹稍減輕,手臂內側皮膚仍有新長紅疹改善,腰際皮膚搔抓紅疹改善,四肢零星,起床流鼻\n水,減少,腳底汗泡疹消失,飲食衛教,衣著不要太緊',NULL,NULL,NULL,'L309','皮膚炎',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'預約報到過號',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,300,0,0,0,0,NULL,NULL,0,0,600,0,100,600,600,NULL,NULL,'現金','現金',NULL,'True','False','True','False','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-06-27 02:08:57');
