INSERT INTO `cases` VALUES (798,104,'^林筠喬','2025-07-08 08:20:46',NULL,'2025-07-08 08:30:48','2025-07-08 08:30:48','複診','內科','預約門診',NULL,'自費','普通疾病','99','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,1,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'20210302\n主訴:全身皮膚炎搔抓,數月\n現病史:臉頰紅疹,手肘內,膕窩,脖項皮膚炎紅腫,耳,頭皮搔抓\n202507/08手肘內紅疹  癢作咳嗽 打噴嚏,流鼻水 鼻塞作減輕,大腿內側皮膚起紅疹塊,皮膚背癢作改善少,皮膚微乾,衛教衣著,',NULL,NULL,NULL,'L209','異位性皮膚炎',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,1420,0,0,0,0,NULL,NULL,0,0,1720,0,100,1720,1720,NULL,NULL,'現金','現金',NULL,'True','False','True','True','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-07-08 00:36:08');
INSERT INTO `cases` VALUES (799,544,'^余瑞珠','2025-07-08 08:23:01',NULL,'2025-07-08 08:38:15','2025-07-08 08:38:15','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,2,NULL,NULL,1,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'T主訴:頭皮與皮膚斑塊反覆十多年\n病史:頭皮與皮膚斑塊,頭皮斑塊色淡紅稍有鱗屑,下肢斑塊色深紅帶明顯鱗屑。曾至台北市立聯合醫院昆明院區中醫科就診,療效不好。尚未至皮膚科就診(怕類固醇)。 \n眠差易醒,無胃悶胃食道逆流,無胸悶心悸,大便一日一行成條,無口乾渴。個性較急。\n2025/07/08 口苦近嚴重,夜間口乾減輕,飲食不節,胃嘈雜 胃泛酸作 衛教飲食,有改善  小腿後側病灶紅斑塊結節,疤痕暗沉,,指甲乾癬作,天氣變化皮膚癢作,少有頭皮膚红斑塊, 壓力大,頭皮屑作,',NULL,NULL,NULL,'L409','乾癬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'收',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,4863,0,0,0,0,NULL,NULL,0,0,5163,0,100,5160,5160,NULL,NULL,'現金','現金',NULL,'True','False','True','True','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-07-08 06:09:34');
INSERT INTO `cases` VALUES (800,956,'^陶季葳','2025-07-08 08:25:25',NULL,'2025-07-08 08:48:52','2025-07-08 08:48:52','複診','內科','預約門診',NULL,'自費','普通疾病','99','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,3,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'T  後頸皮膚搔抓苔蘚化粗, 肘內, 膕窩',NULL,NULL,NULL,'L209','異位性皮膚炎',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'報稅',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,3100,0,0,0,0,NULL,NULL,0,0,3400,0,100,3400,3400,NULL,NULL,'現金','現金',NULL,'True','False','True','True','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-07-08 00:52:52');
INSERT INTO `cases` VALUES (801,242,'呂慶慧','2025-07-08 08:28:08',NULL,'2025-07-08 09:33:38','2025-07-08 09:33:38','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,4,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:雙小腿,臀部,手肘,頭皮紅斑塊約十多年\n現病史:雙小腿,臀部,手肘,頭皮紅斑塊约十多年,曾接受中西醫治樣,症狀反覆,最近雙腿紅斑塊大,加重,不癢,但脫屑多-目前仍有服西藥納可,二便正常,約二天一行.眠差,不易入睡停經一年多有時覺潮熱盜汗\n2025/07/08 口臭,天熱 睡不好,脖項,皮膚癢 天熱作,衣著不當,造成乾燥,搔癢作,小腿皮膚泛紅嚴重 乾癬红斑塊 大片,有屑,零星色素斑,潮熱減輕,心悸,便秘作\n脖頸濕疹作癢,',NULL,NULL,NULL,'L400','尋常性乾癬','L308','其他特定皮膚炎',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,1820,0,0,0,0,NULL,NULL,0,0,2120,0,100,2120,2120,NULL,NULL,'現金','現金',NULL,'True','False','True','True','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-07-08 01:33:49');
