INSERT INTO `cases` VALUES (803,249,'陳維璟','2025-07-08 08:31:20',NULL,'2025-07-08 09:08:04','2025-07-08 09:08:04','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,6,NULL,NULL,2,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:皮膚紅斑塊反覆#*refused\n現病史:皮膚乾癬十多年,TBSA>2%,先前西醫治療中,但背部皮膚紅斑塊未改善,手掌易乾裂,胃泛酸脹輕微發作,二便正常\n2025/07/08  飲食不節 胃食道逆流,胃泛酸 有改善 乾癬持平,睡眠好,坐息正常,運動衛教 乾癬 小腿皮膚病灶持績減輕中,晨起口乾舌燥,衛教飲食後,有改善',NULL,NULL,NULL,'L400','尋常性乾癬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,1188,0,0,0,0,NULL,NULL,0,0,1488,0,100,1480,1480,NULL,NULL,'現金','現金',NULL,'True','False','True','True','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-07-08 01:19:00');
INSERT INTO `cases` VALUES (804,775,'^高寧希','2025-07-08 08:38:02',NULL,'2025-07-08 09:15:48','2025-07-08 09:15:48','複診','內科','預約門診',NULL,'自費','普通疾病','99','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,7,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'T 主訴:全身皮膚炎嚴重,泛紅有滲液\n現病史:全身皮膚炎發作自出生作,全身红红腫有滲液,頭皮膚臉乾燥有結痂 頭皮癢作 臉紅疹 手腕,腳踝粗,厚,小腿外側斑塊,蕁麻疹作,流鼻水,鼻塞,呼吸聲大,晨打噴嚏作, 眼周皮膚紅, 搔抓, 皮膚癢反覆\n2025/007/08 夜間搔抓手腕皮膚苔蘚化粗減輕,搔抓,減少 大腿皮膚红疹多改善,手肘病灶粗, 晨起流鼻水減少,打噴嚏作有改善,',NULL,NULL,NULL,'L209','異位性皮膚炎',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'T',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,2950,0,0,0,0,NULL,NULL,0,0,3250,0,100,3250,3250,NULL,NULL,'現金','現金',NULL,'True','False','True','True','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-07-08 01:21:05');
INSERT INTO `cases` VALUES (805,1257,'葉聿宸','2025-07-08 08:39:49',NULL,'2025-07-08 09:26:29','2025-07-08 09:26:29','複診','內科','預約門診',NULL,'自費','普通疾病','82','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,8,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'@全身皮膚癢搔抓嚴重, 腿皮膚濕疹塊液, 膕窩, 腹部紅疹, \n吃甜食惡化, 流鼻水\n2025/06/25 右小腿濕疹塊減輕, 晨起黃鼻涕，\n\n2025/07/08  左小腿濕疹塊作, 鼻水多',NULL,NULL,NULL,'L239','過敏性接觸性皮膚炎，未明示原因','J309','過敏性鼻炎',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,1280,0,0,0,0,NULL,NULL,0,0,1580,0,100,1580,1580,NULL,NULL,'現金','現金',NULL,'True','False','True','True','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-07-08 01:38:29');
INSERT INTO `cases` VALUES (806,479,'^鍾惠娜','2025-07-08 08:47:21',NULL,'2025-07-08 09:41:15','2025-07-08 09:41:15','複診','內科','預約門診',NULL,'自費','普通疾病',NULL,'基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,9,NULL,NULL,3,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'T 主訴:手掌指間處水泡癢疹10年\n現病史:患者十年前因不明原因手掌小魚際出現紅疹水泡,後指間手腕處也出現癢疹水泡,搔抓滲出組織液,季節轉換時症狀加重。使用天然肥皂洗手症狀減輕,使用冷水沖洗後癢的症狀 \n2025/07/08 月經量大,子宮肌瘤開刀,.  手指腹皮膚炎作,腳趾皮膚炎起泡熱潮濕作,衛教,手前臂皮膚粗疹,刺,癢作,大趾外側粗,乾 經常碰水 拇指,甲溝炎, 作\n血紅素低',NULL,NULL,NULL,'L308','其他特定皮膚炎',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'T',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,2736,0,0,0,0,NULL,NULL,0,0,3036,0,100,3030,3030,NULL,NULL,'現金','現金',NULL,'True','False','True','True','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-07-08 01:52:14');
