INSERT INTO `cases` VALUES (815,694,'吳玲玲','2025-07-08 10:05:17',NULL,'2025-07-08 10:58:10','2025-07-08 10:58:10','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,18,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:皮膚紅斑癢反覆10年以上\n現病史:乾癬2016小腿皮膚红斑塊治,在亞東照光治療十年,小腿皮膚病灶紅斑塊仍有,鳞屑多,胃嘈雜作,睡不好\n2025/05/20不規則服中藥,小腿手臂皮膚紅斑塊仍有,不規則服藥,擦藥膏皮膚癢減,,胃少不適,眠尚可,BP 140/90 mmHg,\n2025/07/08 腿皮膚乾燥紅疹塊.',NULL,NULL,NULL,'L409','乾癬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'預約報到過號',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,2400,0,0,0,0,NULL,NULL,0,0,2700,0,100,2700,2700,NULL,NULL,'現金','現金',NULL,'True','False','True','True','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-07-08 02:59:48');
INSERT INTO `cases` VALUES (816,153,'^陳燦','2025-07-08 10:06:59',NULL,'2025-07-08 11:07:10','2025-07-08 11:07:10','複診','內科','預約門診',NULL,'自費','普通疾病','99','三歲兒童','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,19,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:臉皮膚紅疹\n現病史:臉頰紅疹,搔抓,脖頸皮膚红\n近頭皮膚搔抓 臉红疹仍有多,红腫,腹部皮膚 有粗疹厚,腰腹搔抓,臉皮膚紅腫傷口  \n2025/05/24 下雨天, 皮膚炎惡化, 現臉皮膚紅腫\n2025/06/11 右臉改善, 左臉眼下搔抓傷口紅, 手肘改善\n2025/07/08 腳踝皮膚苔蘚化粗厚,',NULL,NULL,NULL,'L2089','其他異位性皮膚炎','L239','過敏性接觸性皮膚炎，未明示原因',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,12750,0,0,0,0,NULL,NULL,0,0,13050,0,100,13050,13050,NULL,NULL,'現金','現金',NULL,'True','False','True','True','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-07-08 03:11:03');
INSERT INTO `cases` VALUES (817,112,'姚慧娟','2025-07-08 10:20:30',NULL,'2025-07-08 11:24:17','2025-07-08 11:24:17','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,20,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:皮膚鳞屑反覆\n現病史:乾癬41年,乾癬皮膚位手肘、小腿红斑大片,指甲剝離點藥改善,吃辛味皮膚復發,天冷皮膚作,頻尿改善,心血管危險因子抽血檢查.\n2025/07/08 左小腿有红斑塊红疹大片改善較少,冬天惡化,腿皮膚红斑塊增多。吃麻油雞,指甲病灶碰水加重 會痛 載手套,,癢搔抓暗褐,潮熱流汗反復,胃脹不適改善,指關節腫脹,',NULL,NULL,NULL,'L409','乾癬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,1920,0,0,0,0,NULL,NULL,0,0,2220,0,100,2220,2220,NULL,NULL,'現金','現金',NULL,'True','False','True','True','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-07-08 03:39:02');
