INSERT INTO `cases` VALUES (830,1012,'王瑩宏','2025-07-09 08:49:11',NULL,'2025-07-09 09:27:05','2025-07-09 09:27:05','初診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,4,NULL,NULL,3,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'2019/01/14\n主訴:全身皮膚红斑塊反覆 逾4年\n現病史:病患自述皮膚红斑塊反覆逾4年,以大腿最為嚴重。病灶區色鲜紅,皮損邊缘明顯,有凸起、增厚、苔蘚化、脫屑、色素沈積、粗乾,指甲變形、增厚、甲床剝離、點狀凹陷, 。纳可,眠可,二便平。\n2025/07/09 手臂皮膚紅斑塊 右小腿红斑塊大片,乾燥有屑,左腿零星,頭皮屑多,衛教用藥方法,膝關節退化,膝腿皮開刀,後枕頭皮癢 腰腹部皮膚紅斑塊,指甲生長異常改善,胃痛,胃泛酸作飲食衛教,改善,偶發作,',NULL,NULL,NULL,'L400','尋常性乾癬','K3189','胃及十二指腸其他的疾病',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'G',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,2182,0,0,0,0,NULL,NULL,0,0,2482,0,100,2480,2480,NULL,NULL,'現金','現金',NULL,'True','False','True','True','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-07-09 02:49:38');
INSERT INTO `cases` VALUES (831,936,'王觀紓','2025-07-09 08:49:16',NULL,'2025-07-09 09:35:35','2025-07-09 09:35:35','初診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,5,NULL,NULL,4,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'2019/08/20\n主訴:後頸乾癬反復\n現病史:病患自訴下腹抽痛已1年,曾至婦產科,接受超音波檢查,巧克力囊腫5cm,子宮肌腺瘤(2個,2cm,2cm),月經量中,血塊(约十元硬幣大小)痛經 經色鲜紅。納可,眠可, 小便平,大便(一日1-2行腹瀉便秘交替)。下巴痤瘡作,近下腹常抽痛\n2025/05/27 經痛稍有減輕,後枕頭頸皮膚紅斑塊持平,肩頸,腹部腰際,大腿皮膚癢,新長红疹,天冷易作 睡前服中藥胃痛作,,睡9PM-3AM少,下腹抽痛1-2作/週(ovary cysts)已,  晨起胃痛減輕 較晚吃飯,胃食逆流反復,檢查有食道癌前病變,衛教飲食,晚睡\n2025/07/06 月經三個月未至, 子宮內膜厚,  腹脹氣',NULL,NULL,NULL,'L400','尋常性乾癬','K3189','胃及十二指腸其他的疾病',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,958,0,0,0,0,NULL,NULL,0,0,1258,0,100,1250,1250,NULL,NULL,'現金','現金',NULL,'True','False','True','True','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-07-09 02:49:39');
INSERT INTO `cases` VALUES (832,1011,'張慧萍','2025-07-09 08:49:20',NULL,'2025-07-09 09:42:24','2025-07-09 09:42:24','初診','內科','預約門診',NULL,'自費','普通疾病',NULL,'基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,6,NULL,NULL,5,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'2019/01/14\n主訴:全身膨疹發作 反覆已2年\n現病史:病患自述全身皮膚,病灶多發於四肢,服西藥2-4天發一次。病灶區微鮮紅膨疹線條狀,皮劃紋症發作後4小時消失,乾燥 \n2025/07/09 手臂皮膚癢作,睡前和晨起易咳嗽作,白痰多,咽癢,蕁麻疹夜間發  咳嗽痰白, ',NULL,NULL,NULL,'L239','過敏性接觸性皮膚炎，未明示原因','K3189','胃及十二指腸其他的疾病',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'G',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,240,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,2202,0,0,0,0,NULL,NULL,0,0,2502,0,100,2500,2500,NULL,NULL,'現金','現金',NULL,'True','False','True','True','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-07-09 02:49:40');
