INSERT INTO `cases` VALUES (874,463,'吳信賢','2025-07-10 18:35:02',NULL,'2025-07-10 19:11:50','2025-07-10 19:11:50','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'晚班','晚班',1,NULL,41,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'康甯淇',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'2022/11/08\n主訴:全身皮膚紅斑塊多年\n現病史:乾癬多年,紅斑塊病灶位,手臂,後腰背,腿,指甲異常,打噴嚏頻作,偶鼻塞作,胃食道逆流,治療後改善,手臂病灶仍多\n2025/04/08 皮膚乾癬,停藥,天冷皮膚乾燥,紅斑塊又作,,,GERD 服藥改善,少服中藥,202507/10 鼻頭紅斑塊乾燥有屑, ',NULL,NULL,NULL,'L409','乾癬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'預約報到過號',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,700,0,0,0,0,NULL,NULL,0,0,1000,0,100,1000,1000,NULL,NULL,'現金','現金',NULL,'True','False','True','True','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-07-10 11:47:46');
