INSERT INTO `cases` VALUES (877,148,'翁予倢','2025-07-11 08:18:48',NULL,'2025-07-11 08:38:11','2025-07-11 08:38:11','複診','內科','預約門診',NULL,'自費','普通疾病','99','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,1,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:手掌皮濕疹紅腫滲液\n現病史:手肘,膝皮膚搔抓有紅疹,粗,破皮,大腿腹少許,尿布疹2019起治療,本己改善,近手掌皮膚濕疹作,紅腫濕爛 手指皮膚炎泛红,乾燥,膝蓋皮膚粗 手腕皮膚乾燥,紅疹己無\n 掌皮膚濕疹作,紅腫濕爛治療改善,手指縫皮膚炎泛紅,乾燥仍有,膝蓋皮膚粗 手脫皮膚乾燥,紅疹己無,腿皮膚粗\n2025/07/11 手臂皮膚微乾',NULL,NULL,NULL,'L209','異位性皮膚炎',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,1200,0,0,0,0,NULL,NULL,0,0,1500,0,100,1500,1500,NULL,NULL,'現金','現金',NULL,'True','False','True','True','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-07-11 00:44:48');
INSERT INTO `cases` VALUES (878,109,'陳俊伸','2025-07-11 08:20:39',NULL,'2025-07-11 08:49:36','2025-07-11 08:49:36','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,2,NULL,NULL,1,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'20170619\n主訴:頭皮紅斑塊反覆已4年\n現病史:病患自述頭皮紅斑塊反覆已4年,病灶區位於頭皮、鼻子、臀溝處,皮膚色紅、脫屑多、偶癢感冬天較明顯、左手食指指甲凹痕, \n2025/07/10 手肘後皮膚乾粗厚未改善,後枕頭皮膚红斑塊  顳側頭皮病灶癢 作 少,脖頸皮膚癢 衛教飲食 指甲乾癬 衛教少碰水改善',NULL,NULL,NULL,'L400','尋常性乾癬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,2100,0,0,0,0,NULL,NULL,0,0,2400,0,100,2400,2400,NULL,NULL,'現金','現金',NULL,'True','False','True','True','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-07-11 00:58:53');
INSERT INTO `cases` VALUES (879,757,'林立宜','2025-07-11 08:21:55',NULL,'2025-07-11 08:52:34','2025-07-11 08:52:34','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,3,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'2022/07/26\n主訴:頭皮髮際、後背起红斑塊 十多年\n現病史:初起發作於頭皮,胸口、大腿內側與後背皆有發作,2017,5/28生產完後症狀加重,以後背與大腿內側較為嚴重,髮際紅斑塊嚴重,後背斑塊厚\n2025/05/23 近穩定,乾癬位 額頭前左臉髮際紅斑塊會癢作減少,後背紅斑塊,會 後髮際紅斑塊 後背病灶暗沈 飲食衛教,高血脂衛教,睡眠正常.二便可',NULL,NULL,NULL,'L400','尋常性乾癬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,300,0,0,0,0,NULL,NULL,0,0,600,0,100,600,600,NULL,NULL,'現金','現金',NULL,'True','False','True','True','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-07-11 00:58:58');
