INSERT INTO `cases` VALUES (1037,865,'楊乙桓','2025-07-17 18:57:54',NULL,'2025-07-17 19:39:28','2025-07-17 19:39:28','複診','內科','預約門診',NULL,'自費','普通疾病','99','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'晚班','晚班',1,NULL,30,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'李碧涵',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:雙下肢、右手背紅疹發癢约半年。\n現病史:皮膚炎自2023年初發作,發作於雙側小腿,漸及雙側大腿、手背、前臂,以雙側小腿最為嚴重。局部皮膚紅疹,色暗紅,有搔抓傷口,無組織液滲出,皮膚粗糙乾燥、增厚。因癢甚夜眠差,睡眠中不自覺搔抓、會因癢而醒來。 \n2025/07/17  腿皮膚搔抓丘疹多, 流汗搔抓傷口滲液, ',NULL,NULL,NULL,'L209','異位性皮膚炎',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,2910,0,0,0,0,NULL,NULL,0,0,3210,0,100,3210,3210,NULL,NULL,'現金','現金',NULL,'True','False','True','False','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-07-17 11:39:28');
