INSERT INTO `cases` VALUES (1041,578,'孫慶雲','2025-07-18 08:41:19',NULL,'2025-07-18 09:02:20','2025-07-18 09:02:20','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,3,NULL,NULL,2,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'2022/09/07\n主訴:皮膚紅斑塊二年\n現病史:乾癬發作二年以上,西藥治療,控制不佳,全身皮膚红斑塊遍布,指甲異常,體重下降,70->63kg,皮膚癢 \n睡不好 夜間皮膚乾燥搔癢搔抓減少作,,衛教戒菸,己戒菸,外出睡不好,則病灶加重,胃脹不適,胃脹,打嗝,飲食控制改善,頭皮病灶,陰部病灶癢,小腿皮膚 長紅疹搔抓傷口減少,鼻過敏,服西藥癢疹減,頭零星红斑塊,少運動,手指背搔抓红斑塊,衛教少搔抓',NULL,NULL,NULL,'L409','乾癬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,6476,0,0,0,0,NULL,NULL,0,0,6776,0,100,6776,6776,NULL,NULL,'現金','現金',NULL,'True','False','True','True','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-07-18 01:36:20');
