INSERT INTO `cases` VALUES (1140,699,'鄒百倫','2025-07-23 08:25:41',NULL,'2025-07-23 08:40:23','2025-07-23 08:40:23','複診','內科','預約門診',NULL,'自費','普通疾病','99','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,1,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'2017/03/15\n主訴:皮膚炎自出生2個月發作\n現病史:病人母親告知自出生2個月發現臉部及頭皮斑塊,皮膚科診斷異位性皮炎 \n皮屑及搔抓明顯。腹部及四肢外側皮膚粗糙红疹遍2025/07/23 小腿外側皮膚搔抓 ,',NULL,NULL,NULL,'L209','異位性皮膚炎',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,1420,0,0,0,0,NULL,NULL,0,0,1720,0,100,1720,1720,NULL,NULL,'現金','現金',NULL,'True','False','True','True','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-07-23 01:09:10');
INSERT INTO `cases` VALUES (1141,540,'黃美娟','2025-07-23 08:29:49',NULL,'2025-07-23 08:43:13','2025-07-23 08:43:13','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,2,NULL,NULL,1,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'2017.03.20\n主 訴 :乾癬復發\n現病史:皮膚紅色斑塊約10多年。位於手臂、大腿小腿、腰背部。 飲食不節又作,頭皮屑多,頭皮紅斑塊,,四肢皮膚紅斑塊,耳內,皮下出血,\n2025/07/23 指甲乾癬 惡化,手掌皮膚乾燥持續改善,頭皮紅斑塊改善,頭皮頭髮有新長,後項皮膚乾癬癢,紅疹,後背 腿皮紅斑塊 減輕中,頭皮屑多減少,四肢皮膚紅斑塊減少, 内有屑少,',NULL,NULL,NULL,'L409','乾癬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,3264,0,0,0,0,NULL,NULL,0,0,3564,0,100,3560,3560,NULL,NULL,'現金','現金',NULL,'True','False','True','True','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-07-23 01:09:13');
INSERT INTO `cases` VALUES (1142,250,'孫德生','2025-07-23 08:34:08',NULL,'2025-07-23 08:46:55','2025-07-23 08:46:55','複診','內科','預約門診',NULL,'自費','普通疾病',NULL,'基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,3,NULL,NULL,2,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:糖尿病控制不佳\n現病史:糖尿病控制不佳 口腔潰瘍,口角炎,血糖穩定,手痠痛 ,血糖檢查HbAlc,7.0,月底再檢查 sugar ac 98,服DM用藥,外食多手部皮膚濕疹病灶己無,衛教少碰水,無咽痛,無鼻水,胃痛未作, 腰痠痛, 衛教運動減輕,腹部超音波檢查無異常,白內障點藥中,血壓,115/61 HR 76無異常, HbAlc,7.0,sugar ac 98,血糖穩定, 精神改善 700',NULL,NULL,NULL,'E139','其他特定糖尿病，未伴有併發症','L249','刺激性接觸性皮膚炎，未明示原因',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,0,924,0,0,0,0,NULL,NULL,0,0,924,0,100,700,700,NULL,NULL,'現金','現金',NULL,'True','False','True','True','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-07-23 01:12:22');
