INSERT INTO `cases` VALUES (1152,659,'^劉聿程','2025-07-23 10:59:54',NULL,'2025-07-23 11:18:54','2025-07-23 11:18:54','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,13,NULL,NULL,5,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'T主訴:全身皮膚紅斑塊加劇逾五年\n現病史:病患自述四肢、胸腹、腰背、面部、耳後、頭皮紅斑塊,皮膚色鮮紅,病灶邊缘明顯,皮膚增厚乾燥,鱗屑多,癢感稍微,以雙側腳掌及小腿尤甚,吃辣時加劇,水泡無,搔抓有滲組織液,指甲增厚與甲床剝離、點狀凹陷,關節活動正常,曾至皮膚科就診,診斷為乾癬,曾接受外用類固醇軟膏、止癢藥、照光治療,但停藥後症狀反覆難癒。納可、因癢甚眠差,會因癢醒、二便平。睡不佳,夜間癢作,合併糖尿病,高血壓,HbA1c 6.5 sugar ac:110,高血壓服藥,未測量,衛教多運動,注意飲食\n2025/05/19 臉皮膚紅斑塊有屑',NULL,NULL,NULL,'L400','尋常性乾癬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,5900,0,0,0,0,NULL,NULL,0,0,6200,0,100,6200,6200,NULL,NULL,'現金','現金',NULL,'True','False','True','True','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-07-23 03:50:22');
