INSERT INTO `cases` VALUES (1430,252,'李汪德','2025-08-05 08:39:47',NULL,'2025-08-05 09:20:29','2025-08-05 09:20:29','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,6,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:四肢紅斑多年\n現病史:乾癬20+年,冬天加重,經中藥膏治療後現已明顯改善,四肢及背部仍稍有紅斑。變天及喝牛奶時噴嚏易作。二便可,睡眠可,食慾可,\n2025/08/05 天氣變化冷則則作,額皮膚紅斑塊 手臂皮紅斑塊 用暖氣 乾癬 身體紅斑塊 改善,鼻過敏減輕',NULL,NULL,NULL,'L400','尋常性乾癬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,7500,0,0,0,0,NULL,NULL,0,0,7800,0,100,7800,7800,NULL,NULL,'現金','現金',NULL,'True','False','True','True','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-08-05 01:23:37');
