INSERT INTO `cases` VALUES (1436,1008,'許毓峰','2025-08-05 09:35:47',NULL,'2025-08-05 10:03:11','2025-08-05 10:03:11','複診','內科','預約門診',NULL,'自費','普通疾病',NULL,'基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,12,NULL,NULL,2,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:皮膚濕疹發作二年\n現病史:自打疫苗後,皮膚癢疹作,手肘內,手臂,腿窩搔抓苔蘚化粗,身體红疹塊大片,小腿後皮膚紅腫,結痂,\n2025/05/27 晚睡,皮膚炎未有明顯改善,皮膚差,胃不適少作\n2025/07./15 後腿皮膚炎近惡化紅腫, 癢\n2025/07/22 紅腫消退, 乾燥, 暗沈,粗\n2025/008/05 左腿上側仍有結節疹塊,厚',NULL,NULL,NULL,'L239','過敏性接觸性皮膚炎，未明示原因',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,2952,0,0,0,0,NULL,NULL,0,0,3252,0,100,3252,3252,NULL,NULL,'現金','現金',NULL,'True','False','True','True','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-08-05 02:06:33');
