INSERT INTO `cases` VALUES (1442,397,'洪怡瑩','2025-08-05 10:08:57',NULL,'2025-08-05 10:49:22','2025-08-05 10:49:22','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,18,NULL,NULL,5,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'@ 主訴:全身皮膚零星紅斑塊三年\n現病史:乾癬發作三年,臉和臀部病灶癢,頭皮後枕癢,四肢零星,大腿病灶大片,陰部也有,易醒,月經來嚴重經痛,皮膚乾癬,治療改善中,鳞屑減少, 易醒改善\n2025/05/07掉髮多,腳趾乾癬作,後背病灶 頭部皮癢作,腿皮膚红斑塊近惡化,手肘外斑塊改善,月經不規則經痛輕微,衛教運動舒壓\n2025/08/05 經痛,有血塊,  腿皮膚病灶癢,',NULL,NULL,NULL,'L409','乾癬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'預約報到過號',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,400,4675,0,0,0,0,NULL,NULL,0,0,5075,0,100,5075,5075,NULL,NULL,'現金','現金',NULL,'True','False','True','True','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-08-05 03:02:00');
INSERT INTO `cases` VALUES (1443,1401,'陳思涵','2025-08-05 10:12:41',NULL,'2025-08-05 10:56:51','2025-08-05 10:56:51','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,19,NULL,NULL,6,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'@手掌手指皮膚紅斑塊, 癢, \n打疫苖後發作,  腳背紅斑塊癢,  睡眠不佳, 身熱,淺眠,\n2025/07/11 手掌手指, 右腳背皮膚紅斑塊改善\n2025/07/17 睡眠改善, 體熱減輕，\n2025/08/05 手指未端關節腫, 甲溝炎改善, 手掌皮膚厚未改善, 身熱減輕',NULL,NULL,NULL,'L409','乾癬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,3592,0,0,0,0,NULL,NULL,0,0,3892,0,100,3892,3892,NULL,NULL,'現金','現金',NULL,'True','False','True','True','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-08-05 03:17:46');
INSERT INTO `cases` VALUES (1444,1313,'洪郁雯','2025-08-05 10:17:44',NULL,'2025-08-05 11:06:08','2025-08-05 11:06:08','複診','內科','預約門診',NULL,'自費','普通疾病',NULL,'基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,20,NULL,NULL,7,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'@全身皮膚乾燥, 粗, \n自幼濕疹作,類固醇治療, 反覆, 病灶滲液, 上胸熱,刺癢, ,壓迫處癢, 身熱嚴重, 大便硬改善,  \n2025/07/17 夜間癢, 擦複方苦蔘膏過敏, 昨夜癢, 無法入睡 , 用乾癬新M 07/17\n2025/07/22 腋下淋巴結腫, 腋下和肘內乾粗癢\n2025/07/29 入睡困難, 皮膚乾燥癢 明天白內障開刀\n皮膚擦油易有毛囊炎作, 左顳濕疹塊, 月經延後06/24.\n2025/08/05 睡眠改善, 腋下, 手肘皮膚痛, 月經前腰痠,頭痛, 皮膚惡化',NULL,NULL,NULL,'L239','過敏性接觸性皮膚炎，未明示原因',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,4181,0,0,0,0,NULL,NULL,0,0,4481,0,100,4481,4481,NULL,NULL,'現金','現金',NULL,'True','False','True','True','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-08-05 03:50:42');
