INSERT INTO `cases` VALUES (1446,194,'馮美雲','2025-08-05 10:23:20',NULL,'2025-08-05 11:33:38','2025-08-05 11:33:38','複診','內科','預約門診',NULL,'自費','普通疾病',NULL,'基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,22,NULL,NULL,10,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:兩臉頰處紅斑1年\n現病史:患者1年前因不明原因兩臉頰出現紅斑,部分病灶處起丘疹,自覺緊繃感,偶有癢感,搔抓滲出組織液,偶爾眼睛周圍會癢。曾在皮膚科,懷疑是玫瑰疹使用外用藥膏metrenidazone治療後症狀改善,但仍偶有感,有壓力時症狀會較明顯。已停經。二便可。睡眠可。 Tchol:228,衛教\n 2025/08/05  暈眩改善, 手臂內側紅疹癢, 眼',NULL,NULL,NULL,'L239','過敏性接觸性皮膚炎，未明示原因',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'預約報到過號',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,3544,0,0,0,0,NULL,NULL,0,0,3844,0,100,3844,3844,NULL,NULL,'現金','現金',NULL,'True','False','True','True','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-08-05 04:12:49');
