INSERT INTO `cases` VALUES (1569,1013,'吳峻次','2025-08-11 14:59:59',NULL,'2025-08-11 15:30:12','2025-08-11 15:30:12','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'午班','晚班',1,NULL,2,NULL,NULL,1,NULL,NULL,NULL,'林胤谷',NULL,NULL,'范詩豔',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:自國三起乾癣發作\n現病史:自國三起乾癬發作,現腹部和頭皮膚紅斑塊厚,大片,腳少許\n2025/05/27 腹部紅斑塊,早起變淡,後背皮膚新長病灶作減少,皮膚病灶泛紅,乾燥,頭皮膚發紅,乾燥屑多,毛囊炎腫痛,天熱流汗 近未作,體重110減至80多公斤,晚睡>11,,再次衛 教飲食',NULL,NULL,NULL,'L400','尋常性乾癬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,3302,0,0,0,0,NULL,NULL,0,0,3602,0,100,3600,3600,NULL,NULL,'現金','現金',NULL,'True','False','True','True','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-08-11 07:40:26');
INSERT INTO `cases` VALUES (1570,27,'徐若婷','2025-08-11 15:02:37',NULL,'2025-08-11 15:34:26','2025-08-11 15:34:26','複診','內科','預約門診',NULL,'自費','普通疾病','99','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'晚班','晚班',1,NULL,3,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'范詩豔',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴: 四肢, 腰背牽連臀部泛發紅色搔癢丘疹超過五週\n現病史: 五週前四肢, 腰背牽連臀部突發性紅色搔癢丘疹, 無明確誘發因子/加重因子, 現病灶於四肢/手腳掌/手指腳趾與腰背/臀部, 以膝蓋最甚, 丘疹色紅且搔癢, 搔抓出血且滲組織液, 偶脫屑. 西醫診斷為濕疹, 塗抹類固醇可改善, 停藥後復發, 因癢甚影響睡眠. \n食慾可, 大便一天一行, 羊屎便, 小便可',NULL,NULL,NULL,'L209','異位性皮膚炎',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,440,0,0,0,0,NULL,NULL,0,0,740,0,100,740,740,NULL,NULL,'現金','現金',NULL,'True','False','True','True','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-08-11 07:43:06');
