INSERT INTO `cases` VALUES (1575,141,'陳芝言','2025-08-11 16:17:10',NULL,'2025-08-11 16:34:30','2025-08-11 16:34:30','複診','內科','預約門診',NULL,'自費','普通疾病','99','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'晚班','晚班',1,NULL,8,NULL,NULL,3,NULL,NULL,NULL,'林胤谷',NULL,NULL,'范詩豔',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'2018/05/10\n主訴:全身皮膚紅疹片約四個月\n現病史:三個半月大起四肢關節處起红疹點與紅疹片,近來臉部 頸部及前胸紅疹加重,皮膚乾燥脫屑,嚴重時滲流組織液,天氣冷交替明顯時症加重, 目前臉部 頸部 上背部 手背腳背與四肢關節處有紅疹片伴隨脫屑 有輕微搔抓皮膚破損,四肢病灶明顯增厚,臉部大腿經常搔抓 擦西藥有減緩,半夜三點左右搔抓劇烈影響睡眠,近來外陰部處皮膚有發红,',NULL,NULL,NULL,'L309','皮膚炎','L209','異位性皮膚炎',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'預約報到過號',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,9712,0,0,0,0,NULL,NULL,0,0,10012,0,100,10012,10012,NULL,NULL,'現金','現金',NULL,'True','False','True','True','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-08-11 08:58:02');
