INSERT INTO `cases` VALUES (1593,140,'蔡弘源','2025-08-12 08:19:15',NULL,'2025-08-12 08:44:16','2025-08-12 08:44:16','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,1,NULL,NULL,1,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:乾癬十年惡化\n現病史:乾癬發作約十年,近惡化,臉,頭皮,後背,四肢皮膚外側紅斑塊大片,LMD中藥治療未改善,睡眠偶不好手臂濕疹改善,腰側皮膚乾癬紅斑塊改善變平,,手臂皮膚 長紅疹,皮膚癢作,肩有病灶,已少鼻過敏\n2025.07/15 改用新藥, 乾癬紅斑塊改善, 變淡',NULL,'免',NULL,'L400','尋常性乾癬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,16458,0,0,0,0,NULL,NULL,0,0,16758,0,100,16758,16758,NULL,NULL,'現金','現金',NULL,'True','False','True','True','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-08-12 00:57:51');
