INSERT INTO `cases` VALUES (1640,1689,'蔡紹琪','2025-08-14 16:13:25',NULL,'2025-08-14 16:31:01','2025-08-14 16:31:01','複診','內科','預約門診',NULL,'自費','普通疾病',NULL,'基層醫療','自費','申報','不申報','免卡',NULL,NULL,'晚班','晚班',1,NULL,12,NULL,NULL,4,NULL,NULL,NULL,'林胤谷',NULL,NULL,'李碧涵',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'2024 皮膚炎作, 今年親人去世日光性皮膚炎, 擦抗生素, 全身性濕疹作,  壓力大, 睡眠不足,\n2025/08/07 皮膚紅腫減輕, 乾燥, 經痛, 子宮肌腺症, 肛門尾骨痛\n2025/08/14 睡眠改善, 流汗, 腰際和腹胸, 毛囊炎作',NULL,NULL,NULL,'L239','過敏性接觸性皮膚炎，未明示原因',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,2918,0,0,0,0,NULL,NULL,0,0,3218,0,100,3218,3218,NULL,NULL,'現金','現金',NULL,'True','False','True','True','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-08-14 09:28:41');
INSERT INTO `cases` VALUES (1641,31,'丁士宗','2025-08-14 16:40:04',NULL,'2025-08-14 17:00:00','2025-08-14 17:00:00','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'晚班','晚班',1,NULL,13,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'李碧涵',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:皮膚紅斑塊約八年\n現病史:35歲起頭皮紅斑塊, 曾接受西醫類固醇治療有改善, 停藥後反覆發作, 無照光或內服藥治療. 目前皮膚病灶分布於手掌, 手背, 雙臂上側, 小腿, 大退內側大片; 抓出血結紅痂, 伴有鱗屑, BSA 15%, 手指甲點狀凹陷四五年, 目前服抗憂鬱藥物(憂鬱症輕症), 目前工作壓力尚可, 睡眠可, 食慾可, 無胃脹氣不適感, 大便平, 鼻過敏症狀, 無胃食道逆流, 有脂肪肝\n後頸, 皮膚斑塊改善又作\n2025/08/14 明顯有改善,',NULL,NULL,NULL,'L409','乾癬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,5400,0,0,0,0,NULL,NULL,0,0,5700,0,100,5700,5700,NULL,NULL,'現金','現金',NULL,'True','False','True','True','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-08-14 09:28:42');
