INSERT INTO `cases` VALUES (1658,590,'任芷萱','2025-08-15 09:35:54',NULL,'2025-08-15 09:43:49','2025-08-15 09:43:49','複診','內科','預約門診',NULL,'自費','普通疾病','99','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,5,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'2016/11/15\n主訴:手肘內皮膚乾粗紅,\n現病史:病人母親告知自出生6個月,皮膚炎發作於面部,耳後及四肢起紅斑塊,用固醇類軟膏治療,現在於雙手掌及雙腳掌皮膚稍红表面粗糙,小腿稍有紅斑,及小紅疹,平時使用抗組織胺及中藥塗抹,睡前癢甚,吃到過敏物質會難睡, 膕窩 皮膚乾燥 搔抓苔蘚化稍有改善,手肘內側皮膚苔蘚化粗乾燥有屑多減輕 晚睡,夜間搔癢,手指皮膚乾裂 腳背皮膚苔蘚化 乾粗明顯, ,偶流鼻 水,打噴嚏,',NULL,NULL,NULL,'L209','異位性皮膚炎',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'預約報到過號',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,2840,0,0,0,0,NULL,NULL,0,0,3140,0,100,3140,3140,NULL,NULL,'現金','現金',NULL,'True','False','True','False','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-08-15 02:25:48');
