INSERT INTO `cases` VALUES (1949,76,'魏瑞琴','2025-08-27 10:31:50',NULL,'2025-08-27 11:12:32','2025-08-27 11:12:32','複診','內科','一般門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,21,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:雙側小腿、手肘皮膚紅斑塊反覆逾十年\n現病史:病患自述雙側小腿、手肘及前臂皮膚红斑塊反覆逾十年,皮膚色鲜红,病灶邊緣明顯,皮膚乾燥增厚,屑多,癢感稍微,水泡無,搔抓無滲组織液,指甲無異狀,關節活動正常,十幾年前曾至馬借皮膚科就診,診斷為乾癬,曾接受外用類固醇藥膏、照光治療,但效果有限,且停藥後症狀反覆難癒。曾至中醫診所使用口服科中治療,自覺症狀有改善。納可、平素眠差,與癢無關,大便每日可解,質成形,小便平順。\n2 手肘外側皮膚紅斑塊,腳膝也有, 不太想吃中藥',NULL,NULL,NULL,'L409','乾癬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,2750,0,0,0,0,NULL,NULL,0,0,3050,0,100,3050,3050,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-08-27 03:35:29');
