INSERT INTO `cases` VALUES (2082,1313,'洪郁雯','2025-09-02 10:30:39',NULL,'2025-09-02 10:50:36','2025-09-02 10:50:36','複診','內科','預約門診',NULL,'自費','普通疾病',NULL,'基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,14,NULL,NULL,9,NULL,NULL,NULL,'林胤谷',NULL,NULL,'游惠玲',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'@全身皮膚乾燥, 粗, \n自幼濕疹作,類固醇治療, 反覆, 病灶滲液, 上胸熱,刺癢, ,壓迫處癢, 身熱嚴重, 大便硬改善,  \n2025/07/17 夜間癢, 擦複方苦蔘膏過敏, 昨夜癢, 無法入睡 , 用乾癬新M 07/17\n2025/07/22 腋下淋巴結腫, 腋下和肘內乾粗癢\n2025/07/29 入睡困難, 皮膚乾燥癢 明天白內障開刀\n皮膚擦油易有毛囊炎作, 左顳濕疹塊, 月經延後06/24.\n2025/08/12  睡眠改善, 腋下, 手肘皮膚痛稍減, 乾燥癢, , 08/10月經前腰痠,頭痛, 皮膚惡化\n08/18 月經來,7日,量減少, 經來腹部悶痛作\n2025/08/26 自覺身體濕, 有氣味,\n2025/09/02 身熱,脖頸皮膚粗, ',NULL,NULL,NULL,'L239','過敏性接觸性皮膚炎，未明示原因',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'預約報到過號',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,4834,0,0,0,0,NULL,NULL,0,0,5134,0,100,5134,5134,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-09-02 03:21:25');
INSERT INTO `cases` VALUES (2083,848,'薛晴安','2025-09-02 10:43:26',NULL,'2025-09-02 10:54:05','2025-09-02 10:54:05','複診','內科','預約門診',NULL,'自費','普通疾病','99','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,15,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'游惠玲',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'@主訴:皮膚搔癢自出生2個月發作\n現病史:皮膚炎自出生2個月發作,發作於臉部、耳後、頭部、上肢(手肘)、下肢(膝膕窩)、軀幹(腰背部右臀部、會陰),以臉部最為嚴重。局部皮膚红疹,色红,有搔抓滲出,皮膚乾燥,因癢甚夜眠差,睡眠中不自覺搔抓、不會醒來。曾使用西醫類固醇外用、口服抗組織胺和類固醇治療,鼻涕使用後症狀有改善,皮膚症狀有些微改善',NULL,NULL,NULL,'L209','異位性皮膚炎',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,7610,0,0,0,0,NULL,NULL,0,0,7910,0,100,7910,7910,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-09-02 03:15:33');
