INSERT INTO `cases` VALUES (2085,1802,'莊泳沐','2025-09-02 13:55:15',NULL,'2025-09-02 14:32:40','2025-09-02 14:32:40','複診','內科','預約門診',NULL,'自費','普通疾病',NULL,'基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','午班',1,NULL,17,NULL,NULL,11,NULL,NULL,NULL,'特約門診',NULL,NULL,'張介雪',NULL,'特約門診',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'十年前, 手肘, 耳後皮膚乾紅斑塊, 皮膚炎四年前惡化, \n數月前泡湯後惡化, 現全身泛紅疹大片, \n杜必炎治療, 效不佳, 類固醇注射控制\n嚴重皮膚癢,睡不好, 水便,\n2025/08/26 稍有退紅, 但夜間癢, 睡不好, 腳趾痛風腫痛,  皮膚乾燥','91Kg',NULL,NULL,'L239','過敏性接觸性皮膚炎，未明示原因',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,0,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,1500,14216,0,0,0,0,NULL,NULL,0,0,15716,0,100,15716,15716,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-09-02 06:51:49');
