INSERT INTO `cases` VALUES (2097,659,'劉聿程','2025-09-03 10:02:50',NULL,'2025-09-03 10:10:28','2025-09-03 10:10:28','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,12,NULL,NULL,7,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'T主訴:全身皮膚紅斑塊加劇逾五年\n現病史:病患自述四肢、胸腹、腰背、面部、耳後、頭皮紅斑塊,皮膚色鮮紅,病灶邊缘明顯,皮膚增厚乾燥,鱗屑多,癢感稍微,以雙側腳掌及小腿尤甚,吃辣時加劇,水泡無,搔抓有滲組織液,指甲增厚與甲床剝離、點狀凹陷,關節活動正常 合併糖尿病,高血壓,HbA1c 6.5 sugar ac:110,高血壓服藥, \n2025/09/03 皮膚紅斑塊有屑. 近未改善',NULL,NULL,NULL,'L400','尋常性乾癬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,8600,0,0,0,0,NULL,NULL,0,0,8900,0,100,8900,8900,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-09-03 02:18:35');
INSERT INTO `cases` VALUES (2098,397,'洪怡瑩','2025-09-03 10:13:52',NULL,'2025-09-03 10:27:06','2025-09-03 10:27:06','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,13,NULL,NULL,8,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'@ 主訴:全身皮膚零星紅斑塊三年\n現病史:乾癬發作三年,臉和臀部病灶癢,頭皮後枕癢,四肢零星,大腿病灶大片,陰部也有,易醒,月經來嚴重經痛,皮膚乾癬,治療改善中,鳞屑減少, 易醒改善\n2025/05/07掉髮多,腳趾乾癬作,後背病灶 頭部皮癢作,腿皮膚红斑塊近惡化,手肘外斑塊改善,月經不規則經痛輕微,衛教運動舒壓\n2025/08/05 經痛,有血塊,  腿皮膚病灶癢,\n2025/09/03 經痛一日, 今日經來, 未痛, 緊張皮膚癢搔抓',NULL,NULL,NULL,'L409','乾癬','F410','特定場所畏懼症的恐慌症',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'預約報到過號',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,3885,0,0,0,0,NULL,NULL,0,0,4185,0,100,4185,4185,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-09-03 03:21:11');
