INSERT INTO `cases` VALUES (2379,250,'孫德生','2025-09-17 08:21:44',NULL,'2025-09-17 08:26:36','2025-09-17 08:26:36','複診','內科','預約門診',NULL,'自費','普通疾病',NULL,'基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,1,NULL,NULL,1,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:糖尿病控制不佳\n現病史:糖尿病控制不佳 口腔潰瘍,口角炎,血糖穩定,手痠痛 ,血糖檢查HbAlc,7.0,月底再檢查 sugar ac 98,服DM用藥,外食多手部皮膚濕疹病灶己無,衛教少碰水,無咽痛,無鼻水,胃痛未作, 腰痠痛, 衛教運動減輕,腹部超音波檢查無異常,白內障點藥中, 血壓,114/61 HR 75無異常,  HbAlc,7.0,sugar ac 103 ,血糖穩定, 精神改善 700\n2025/08/20 abd echo test normal. renal stone\n2025/09/17  HbA1c 6.9 BP   111/60  76',NULL,NULL,NULL,'E139','其他特定糖尿病，未伴有併發症','L249','刺激性接觸性皮膚炎，未明示原因',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,0,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,924,0,0,0,0,NULL,NULL,0,0,1224,524,100,700,700,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-09-17 00:37:46');
