INSERT INTO `cases` VALUES (2244,1021,'王睿翔.','2025-09-10 08:17:47',NULL,'2025-09-10 08:34:07','2025-09-10 08:34:07','複診','內科','預約門診',NULL,'自費','普通疾病',NULL,'三歲兒童','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,1,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:腿皮膚搔抓傷口\n現病史:異膚,皮膚癢,腿皮膚搔抓傷口多,潰瘍傷口\n2025/05/28 腿皮膚搔抓傷口多,稍有減少,潰瘍傷口改善\n2025/08/05 腿皮膚疤痕,蟲叮? 皮膚乾粗\n2025/09/10 蕁麻疹作',NULL,NULL,NULL,'L239','過敏性接觸性皮膚炎，未明示原因',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,1200,0,0,0,0,NULL,NULL,0,0,1500,0,100,1500,1500,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-09-10 00:35:34');
INSERT INTO `cases` VALUES (2245,775,'高寧希.','2025-09-10 08:19:36',NULL,'2025-09-10 08:42:43','2025-09-10 08:42:43','複診','內科','預約門診',NULL,'自費','普通疾病','99','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,2,NULL,NULL,1,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'T 主訴:全身皮膚炎嚴重,泛紅有滲液\n現病史:全身皮膚炎發作自出生作,全身红红腫有滲液,頭皮膚臉乾燥有結痂 頭皮癢作 臉紅疹 手腕,腳踝粗,厚,小腿外側斑塊,蕁麻疹作,流鼻水,鼻塞,呼吸聲大,晨打噴嚏作, 眼周皮膚紅, 搔抓, 皮膚癢反覆\n2025/009/10   夜間搔抓手腕皮膚苔蘚化粗減輕,搔抓,減少 大腿皮膚红疹多改善,手肘病灶粗, 晨起流鼻水減少,打噴嚏作有改善,',NULL,NULL,NULL,'L209','異位性皮膚炎',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,7884,0,0,0,0,NULL,NULL,0,0,8184,0,100,8184,8184,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-09-10 00:56:27');
