INSERT INTO `cases` VALUES (2365,1427,'楊淑慧','2025-09-16 09:30:14',NULL,'2025-09-16 09:36:36','2025-09-16 09:36:36','複診','內科','預約門診',NULL,'自費','普通疾病',NULL,'基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,5,NULL,NULL,1,NULL,NULL,NULL,'林胤谷',NULL,NULL,'許梅卿',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'吃降酸藥, 2025/03 皮膚炎發作, 初起腳側, 後腿和手臂內側紅疹紅腫,不痛,癢 \n胃不好, 甲狀腺低下, 血脂高, 高血壓\n2025/07/25   腳踝腫脹, 泛紅, 手臂紅腫減輕. 便秘改善\n2025/08/01  腳踝紅腫減輕, 手臂內側紅腫改善，\n2025/08/20 明顯改善, 在慈濟吃中藥\n2025/08/26 腿皮膚搔抓, 紅腫.  倦怠無力\n2025/09/16 左手臂內側紅腫, 小腿又搔抓紅腫, ',NULL,NULL,NULL,'L239','過敏性接觸性皮膚炎，未明示原因',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,5663,0,0,0,0,NULL,NULL,0,0,5963,0,100,5963,5963,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-09-16 02:26:34');
INSERT INTO `cases` VALUES (2366,52,'趙浚宏','2025-09-16 09:52:17',NULL,'2025-09-16 09:58:15','2025-09-16 09:58:15','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,6,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'許梅卿',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:手肘和小腿紅斑塊多年\n現病史:手肘和小腿紅斑塊多年, 頭皮也有, 小腿紅斑塊明顯, 會癢, 指甲增厚, 胃偶不適, 大便硬. 近2個月腿皮膚病灶紅斑塊紅腫加重, 乾裂, 近期檢查血糖高127, PASI13.2\n250402 小腿皮膚乾癬紅斑塊改善又作, 乾燥, 手臂皮膚天冷長新斑塊, 搔抓紅疹多, 指甲剝離仍明顯, 手背皮膚紅斑, 胃嘈雜改善, 少服\n中藥左臀部紅斑塊,',NULL,NULL,NULL,'L400','尋常性乾癬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,1120,0,0,0,0,NULL,NULL,0,0,1420,0,100,1420,1420,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-09-16 06:03:30');
