INSERT INTO `cases` VALUES (2368,51,'俞建宏','2025-09-16 09:57:24',NULL,'2025-09-16 10:10:37','2025-09-16 10:10:37','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,8,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'許梅卿',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:全身多處紅斑塊20年\n現病史:患者20年前因為不明原因頭皮處出現紅色斑塊, 之後陸陸續續全身, 四肢, 臉部都出現紅色斑塊, 病灶處增厚起; 乾癬持平, 皮膚乾燥, 後輩皮膚紅斑塊鱗屑厚, 大片, 乾燥, 癢作, 衛教運動, 注意飲食, 不規則服藥',NULL,NULL,NULL,'L409','乾癬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'預約報到過號',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,5000,0,0,0,0,NULL,NULL,0,0,5300,0,100,5300,5300,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-09-16 02:26:23');
