INSERT INTO `cases` VALUES (2371,1313,'洪郁雯','2025-09-16 10:27:33',NULL,'2025-09-16 10:35:17','2025-09-16 10:35:17','複診','內科','預約門診',NULL,'自費','普通疾病',NULL,'基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,11,NULL,NULL,4,NULL,NULL,NULL,'林胤谷',NULL,NULL,'張介雪',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'@全身皮膚乾燥, 粗, \n自幼濕疹作,類固醇治療, 反覆, 病灶滲液, 上胸熱,刺癢, ,壓迫處癢, 身熱嚴重, 大便硬改善,  \n2025/07/17 夜間癢, 擦複方苦蔘膏過敏, 昨夜癢, 無法入睡 , 用乾癬新M 07/17\n2025/07/22 腋下淋巴結腫, 腋下和肘內乾粗癢\n2025/07/29 入睡困難, 皮膚乾燥癢 明天白內障開刀\n皮膚擦油易有毛囊炎作, 左顳濕疹塊, 月經延後06/24.\n2025/08/12  睡眠改善, 腋下, 手肘皮膚痛稍減, 乾燥癢, , 08/10月經前腰痠,頭痛, 皮膚惡化\n08/18 月經來,7日,量減少, 經來腹部悶痛作\n2025/08/26 自覺身體濕, 有氣味,\n2025/09/09 仍身熱,脖頸皮膚粗, 身躁熱,易流汗. 月2025/09/16 經09/09 至, 經量多三日, 頭暈, 偏頭痛作, 躁熱減輕作, 一日發2-3次, 眠改善, 經來胸悶,心 悸',NULL,NULL,NULL,'L239','過敏性接觸性皮膚炎，未明示原因',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,3278,0,0,0,0,NULL,NULL,0,0,3578,0,100,3578,3578,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-09-16 02:58:02');
