INSERT INTO `cases` VALUES (2417,657,'曾怡璁.','2025-09-18 18:01:37',NULL,'2025-09-18 18:09:59','2025-09-18 18:09:59','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'晚班','晚班',1,NULL,24,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'范詩豔',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'2017/08/22\n主訴:皮膚紅色斑塊约1年\n現病史:皮膚紅色斑塊约1年。主要位於頭皮。色淡紅增厚,脫屑,不規則形,會搔癢。指甲無影響,關節無影響。曾使用西醫藥膏類固醇治療,但效果平。納可,二便可,眠可。偶發膨疹\n2025/07/14 頭皮多,額皮膚乾癬斑塊新長,腿皮膚斑塊厚,\n2025/09/18 耳後髮際斑塊仍有,',NULL,NULL,NULL,'L400','尋常性乾癬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,2400,0,0,0,0,NULL,NULL,0,0,2700,0,100,2700,2700,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-09-18 10:27:16');
