INSERT INTO `cases` VALUES (2516,524,'徐涵齡','2025-09-22 18:47:26',NULL,'2025-09-22 19:24:51','2025-09-22 19:24:51','複診','內科','預約門診',NULL,'自費','普通疾病',NULL,'基層醫療','自費','申報','不申報','免卡',NULL,NULL,'晚班','晚班',1,NULL,31,NULL,NULL,13,NULL,NULL,NULL,'林胤谷',NULL,NULL,'范詩豔',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:皮膚紅疹搔癢約10年\n現病史:皮膚紅疹搔癢約10年,去年11月開始加重。發作於前手臂.大小腿。局部皮紅疹,色淡紅,有搔抓傷口,搔癢甚,皮膚乾燥,輕微苔蘚化。因癢甚夜眠差 。納可。排便平。胃泛酸。右膝關節炎腫痛 , 改善\n2025/07/28 手臂, 小腿皮膚癢,夜間癢醒,\n2025/09/22 二週前牙齦腫, 服抗生素, 皮膚癢, 睡不好, 身熱, 流汗多, 口苦,',NULL,NULL,NULL,'L239','過敏性接觸性皮膚炎，未明示原因',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,1542,0,0,0,0,NULL,NULL,0,0,1842,0,100,1842,1842,NULL,NULL,'現金','現金',NULL,'True','False','True','False','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-09-22 11:24:51');
INSERT INTO `cases` VALUES (2517,596,'劉姿伶','2025-09-22 18:49:11',NULL,'2025-09-22 19:32:41','2025-09-22 19:32:41','複診','內科','一般門診',NULL,'自費','普通疾病',NULL,'基層醫療','自費','申報','不申報','免卡',NULL,NULL,'晚班','晚班',1,NULL,32,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'范詩豔',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:皮膚紅疹、斑塊約1年多\n現病史:皮紅疹、斑塊约1年多。位於手掌、大腿、背部。色淡红。搔癢、些微脫皮。圓形居多。每次位置不固定。西醫診斷濕疹。曾使用治療:類固醇、抗組織胺。效果平。\n納可。排便2-3日1行質硬。眠因癢而差。易口乾。無泛酸、但飯後易腹脹。\n2025/09/22  腹部皮膚癢作,乾燥,  手臂皮膚粗疹癢, 膕窩小腿皮膚癢',NULL,NULL,NULL,'L239','過敏性接觸性皮膚炎，未明示原因',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,3750,0,0,0,0,NULL,NULL,0,0,4050,0,100,4050,4050,NULL,NULL,'現金','現金',NULL,'True','False','True','False','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-09-22 11:32:41');
