INSERT INTO `cases` VALUES (2553,1752,'張邦琦','2025-09-26 08:30:30',NULL,'2025-09-26 08:40:05','2025-09-26 08:40:05','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,1,NULL,NULL,1,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'2022 膿包乾癬作, 長庚,Dr. 盧治療, \n標杷治療, 懷孕惡化,  腹部紅疹大片, 夜間搔癢, 皮膚緊,身躁熱,發作前倦怠作\n2025/08/21 胸口脖頸灼熱作減少, 泛紅, 夜間搔癢嚴重減輕, 大便一日四行\n2025/09/05 服藥胃脹不適己無,  大便一日一行, 皮膚炎未作,\n20250926  大腿內側紅疹大片減退, 不癢, 身躁熱減輕',NULL,NULL,NULL,'L401','全身性膿疱性乾癬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,1498,0,0,0,0,NULL,NULL,0,0,1798,0,100,1798,1798,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-09-26 01:25:11');
INSERT INTO `cases` VALUES (2554,578,'孫慶雲','2025-09-26 08:31:03',NULL,'2025-09-26 08:44:20','2025-09-26 08:44:20','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,2,NULL,NULL,2,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'2022/09/07\n主訴:皮膚紅斑塊二年\n現病史:乾癬發作二年以上,西藥治療,控制不佳,全身皮膚红斑塊遍布,指甲異常,體重下降,70->63kg,皮膚癢 \n睡不好 夜間皮膚乾燥搔癢搔抓減少作,,衛教戒菸,己戒菸,外出睡不好,則病灶加重,胃脹不適,胃脹,打嗝,飲食控制改善,頭皮病灶,陰部病灶癢,小腿皮膚 長紅疹搔抓傷口減少,鼻過敏,服西藥癢疹減,頭零星红斑塊,少運動,手指背搔抓红斑塊,衛教少搔抓\n2025/09/26 流鼻水, 打噴嚏',NULL,NULL,NULL,'L409','乾癬','J309','過敏性鼻炎',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,9539,0,0,0,0,NULL,NULL,0,0,9839,0,100,9839,9839,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-09-26 01:25:14');
INSERT INTO `cases` VALUES (2555,255,'沙慰慰','2025-09-26 08:34:44',NULL,'2025-09-26 08:49:50','2025-09-26 08:49:50','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,3,NULL,NULL,3,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:乾癬反復20多年\n現病史:皮膚红斑塊位身體,腿,流汗病灶刺痛\n 右手指皮炎,長手泡,會裂改善,其他手指也會皮膚炎,指甲乾癬作 胃食道逆流減輕\n2025/09/26 手指側皮膚炎, 仍有胃泛酸作',NULL,NULL,NULL,'L409','乾癬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,1182,0,0,0,0,NULL,NULL,0,0,1482,0,100,1482,1482,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-09-26 01:25:18');
INSERT INTO `cases` VALUES (2556,1294,'歐淳英','2025-09-26 08:36:21',NULL,'2025-09-26 09:00:51','2025-09-26 09:00:51','複診','內科','預約門診',NULL,'自費','普通疾病',NULL,'基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,4,NULL,NULL,4,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'右手臂外側, 左大腿後, 癢疹塊近惡化, 子宮肌瘤\n怕熱, 易流汗, 心悸, 睡不好',NULL,NULL,NULL,'L239','過敏性接觸性皮膚炎，未明示原因',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,1597,0,0,0,0,NULL,NULL,0,0,1897,0,100,1897,1897,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-09-26 01:25:23');
INSERT INTO `cases` VALUES (2557,540,'黃美娟','2025-09-26 08:36:39',NULL,'2025-09-26 09:04:12','2025-09-26 09:04:12','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,5,NULL,NULL,5,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'2017.03.20\n主 訴 :乾癬復發\n現病史:皮膚紅色斑塊約10多年。位於手臂、大腿小腿、腰背部。 飲食不節又作,頭皮屑多,頭皮紅斑塊,,四肢皮膚紅斑塊,耳內,皮下出血,\n2025/07/23 指甲乾癬 惡化,手掌皮膚乾燥持續改善,頭皮紅斑塊改善,頭皮頭髮有新長,後項皮膚乾癬癢,紅疹,後背 腿皮紅斑塊 減輕中,頭皮屑多減少,四肢皮膚紅斑塊減少, 内有屑少,\n2025/09/26小腿皮膚仍有紅斑塊,',NULL,NULL,NULL,'L409','乾癬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,2364,0,0,0,0,NULL,NULL,0,0,2664,0,100,2664,2664,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-09-26 01:25:27');
