INSERT INTO `cases` VALUES (2562,74,'李璐莎','2025-09-27 07:41:25',NULL,'2025-09-27 07:55:13','2025-09-27 07:55:13','複診','內科','預約門診',NULL,'自費','普通疾病','99','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,1,NULL,NULL,1,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:腿彎曲側紅疹有結痂二週\n現病史:皮膚組,腿彎曲側紅疹有結痂 臉頻紅疹,2019/11/15.治療,四肢屈側紅疹,膝,腳踝苔蘚化,後以西藥控制,近停用西藥,服LMD中藥,惡化,手指皮膚紅腫結痂,手腕苔蘚化嚴重,膕窩也有,流鼻水,打噴嚏作.\n2025/07/26  手腕苔蘚化嚴重厚有 ,手指皮膚红腫結痂已無,乾燥,,膕窩紅癢輕微,流鼻水,打噴嚏減 ,鼻塞  吞口水咽痛, 咳嗽作\n2025/09/27 手腕 仍有苔蘚化粗',NULL,NULL,NULL,'L209','異位性皮膚炎','J309','過敏性鼻炎',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,1758,0,0,0,0,NULL,NULL,0,0,2058,0,100,2058,2058,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-09-27 00:08:55');
