INSERT INTO `cases` VALUES (2598,565,'蘇慶祥','2025-09-27 10:50:53',NULL,'2025-09-27 11:52:27','2025-09-27 11:52:27','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,36,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'宋惠玲',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'2019/02/12\n主訴:全身皮膚紅色斑塊伴隨鱗屑約12年\n現病史:乾癬發作於25歲,曾於皮膚科就診,使用類固醇藥膏可改善。目前乾癬發作於四肢伸側、面頸及腰背部,伴有鱗屑,搔癢感甚,不影響睡眠。\n入睡困難,夢多。食納平,食後腹脹,夜間乾咳,口乾渴,飲不止渴。大便日1行,小便平。\n2025/07/26 手背病灶改善,  睡不好改善,\n2025/08/30 後背紅斑塊大片,',NULL,NULL,NULL,'L400','尋常性乾癬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'預約報到過號',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,5000,0,0,0,0,NULL,NULL,0,0,5300,0,100,5300,5300,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-09-27 03:58:27');
