INSERT INTO `cases` VALUES (2663,710,'賴乙誠','2025-09-30 11:30:38',NULL,'2025-09-30 11:54:33','2025-09-30 11:54:33','複診','內科','一般門診',NULL,'自費','普通疾病','99','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,17,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'張介雪',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'台中 2023/10/25\n主訴:皮膚炎復發\n現病史:皮膚炎自出生5個月發作,發作於足踝 皮膚红腫,有搔抓傷口,本治療改善,近又作,全身皮膚乾燥,脖頸,手臂內,膕窩皮膚紅疹搔抓,腰際皮膚粗, 去日本, 泡溫泉, 惡化\n2025/09/19 手肘內, 脖頸粗疹, 少搔抓. 腿皮膚魚鱗癬狀, 膕窩丘疹苔蘚化仍有\n2025/09/30 更換, 青黛糊劑 7',NULL,NULL,NULL,'L209','異位性皮膚炎',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,4200,0,0,0,0,NULL,NULL,0,0,4500,0,100,4500,4500,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-09-30 05:37:43');
INSERT INTO `cases` VALUES (2664,1802,'莊泳沐','2025-09-30 13:45:02',NULL,'2025-09-30 14:16:32','2025-09-30 14:16:32','複診','內科','預約門診',NULL,'自費','普通疾病',NULL,'基層醫療','自費','申報','不申報','免卡',NULL,NULL,'午班','午班',1,NULL,18,NULL,NULL,10,NULL,NULL,NULL,'林胤谷',NULL,NULL,'張介雪',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'十年前, 手肘, 耳後皮膚乾紅斑塊, 皮膚炎四年前惡化, \n數月前泡湯後惡化, 現全身泛紅疹大片, \n杜必炎治療, 效不佳, 類固醇注射控制\n嚴重皮膚癢,睡不好, 水便,\n2025/09/16 後背退紅, 夜間癢減少, 淺眠, 睡不好, 腳趾痛風腫痛,  皮膚乾燥, 腳踝跟痛, 後背疔瘡\n2025/09/30 手皮膚乾燥脫皮','91Kg',NULL,NULL,'L239','過敏性接觸性皮膚炎，未明示原因','I10','本態性(原發性)高血壓','M109','痛風',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'高血壓 服藥中, DM ?血糖稍高,  注射維生素C',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,1500,10449,0,0,0,0,NULL,NULL,0,0,11949,0,100,11949,11949,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-09-30 06:51:41');
