INSERT INTO `cases` VALUES (2758,140,'蔡弘源','2025-10-07 08:26:31',NULL,'2025-10-07 08:44:46','2025-10-07 08:44:46','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,2,NULL,NULL,1,NULL,NULL,NULL,'林胤谷',NULL,NULL,'許梅卿',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:乾癬十年惡化\n現病史:乾癬發作約十年,近惡化,臉,頭皮,後背,四肢皮膚外側紅斑塊大片,LMD中藥治療未改善,睡眠偶不好手臂濕疹改善,腰側皮膚乾癬紅斑塊改善變平,,手臂皮膚 長紅疹,皮膚癢作,肩有病灶,已少鼻過敏\n2025.07/15 改用新藥, 乾癬紅斑塊改善, 變淡\n2025/10/07 持續改善, 用新配方青香,',NULL,'免',NULL,'L400','尋常性乾癬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,19858,0,0,0,0,NULL,NULL,0,0,20158,0,100,20158,20158,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-10-07 00:56:40');
INSERT INTO `cases` VALUES (2759,249,'陳維璟','2025-10-07 08:28:48',NULL,'2025-10-07 08:46:48','2025-10-07 08:46:48','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,3,NULL,NULL,2,NULL,NULL,NULL,'林胤谷',NULL,NULL,'許梅卿',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:皮膚紅斑塊反覆#*refused\n現病史:皮膚乾癬十多年,TBSA>2%,先前西醫治療中,但背部皮膚紅斑塊未改善,手掌易乾裂,胃泛酸脹輕微發作,二便正常\n2025/07/08  飲食不節 胃食道逆流,胃泛酸 有改善 乾癬持平,睡眠好,坐息正常,運動衛教 乾癬 小腿皮膚病灶持績減輕中,晨起口乾舌燥,衛教飲食後,有改善\n2025/10/07 改善中, ',NULL,NULL,NULL,'L400','尋常性乾癬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,1388,0,0,0,0,NULL,NULL,0,0,1688,0,100,1688,1688,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-10-07 00:58:22');
