INSERT INTO `cases` VALUES (2765,1030,'陳麗月','2025-10-07 10:09:38',NULL,'2025-10-07 10:15:20','2025-10-07 10:15:20','複診','內科','預約門診',NULL,'自費','普通疾病',NULL,'基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,9,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'張介雪',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:乾癬發作10年\n現病史:全身红斑塊反復作 四肢紅斑塊明顯,失眠 天氣變化,乾癬病灶發作红斑塊,腿皮膚病灶 偶癢作,睡眠尚可,自行網路買藥擦\n2025/05/28乾癬皮膚乾燥 癢減輕,手臂皮膚 红斑塊 偶新長,,小腿外側皮膚红斑塊厚,癢,手肘内,腰際乾粗,\n2025/10/07 後背皮膚癢, 手臂',NULL,NULL,NULL,'L239','過敏性接觸性皮膚炎，未明示原因',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,2500,0,0,0,0,NULL,NULL,0,0,2800,0,100,2800,2800,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-10-07 02:20:24');
INSERT INTO `cases` VALUES (2766,397,'洪怡瑩','2025-10-07 10:19:45',NULL,'2025-10-07 10:23:48','2025-10-07 10:23:48','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,10,NULL,NULL,4,NULL,NULL,NULL,'林胤谷',NULL,NULL,'張介雪',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'@ 主訴:全身皮膚零星紅斑塊三年\n現病史:乾癬發作三年,臉和臀部病灶癢,頭皮後枕癢,四肢零星,大腿病灶大片,陰部也有,易醒,月經來嚴重經痛,皮膚乾癬,治療改善中,鳞屑減少, 易醒改善\n2025/05/07掉髮多,腳趾乾癬作,後背病灶 頭部皮癢作,腿皮膚红斑塊近惡化,手肘外斑塊改善,月經不規則經痛輕微,衛教運動舒壓\n2025/09/03 經痛一日, 今日經來,未痛, 緊張皮膚癢搔抓\n2025/10/07 經痛減輕, 右小腿皮膚斑塊改善',NULL,NULL,NULL,'L409','乾癬','F410','特定場所畏懼症的恐慌症',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'預約報到過號',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,5801,0,0,0,0,NULL,NULL,0,0,6101,0,100,6101,6101,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-10-07 02:44:39');
INSERT INTO `cases` VALUES (2767,246,'吳彩有','2025-10-07 10:22:37',NULL,'2025-10-07 10:32:50','2025-10-07 10:32:50','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,11,NULL,NULL,5,NULL,NULL,NULL,'林胤谷',NULL,NULL,'張介雪',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:乾癬50年以上\n現病史:乾癣西醫治療,肛門皮膚泛紅撤,龜頭皮膚有白色斑塊,\n2025/07/01 開刀停藥, 皮膚癢 ,肛門皮膚泛红,龜頭皮膚有白色斑塊 , BPH\n2025/10/07 手臂內側皮膚癢, 晨起咽有痰',NULL,NULL,NULL,'L400','尋常性乾癬','J300','血管舒縮性鼻炎',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'預約報到過號',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,9693,0,0,0,0,NULL,NULL,0,0,9993,0,100,9993,9993,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-10-07 02:51:54');
INSERT INTO `cases` VALUES (2768,1313,'洪郁雯','2025-10-07 10:52:37',NULL,'2025-10-07 10:58:35','2025-10-07 10:58:35','複診','內科','預約門診',NULL,'自費','普通疾病',NULL,'基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,12,NULL,NULL,6,NULL,NULL,NULL,'林胤谷',NULL,NULL,'張介雪',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'@全身皮膚乾燥, 粗, \n自幼濕疹作,類固醇治療, 反覆, 病灶滲液, 上胸熱,刺癢, ,壓迫處癢, 身熱嚴重, 大便硬改善,  \n2025/07/17 夜間癢, 擦複方苦蔘膏過敏, 昨夜癢, 無法入睡 , 用乾癬新M 07/17\n2025/07/29 入睡困難, 皮膚乾燥癢 明天白內障開刀\n皮膚擦油易有毛囊炎作, 左顳濕疹塊, 月經延後06/24.\n2025/08/12  睡眠改善, 腋下, 手肘皮膚痛稍減, 乾燥癢, , 08/10月經前腰痠,頭痛, 皮膚惡化. 08/18 月經來,7日,量減少, 經來腹部悶痛作\n2025/09/09 仍身熱,脖頸皮膚粗, 身躁熱,易流汗. 月2025/09/16 經09/09 至, 經量多三日, 頭暈, 偏頭痛作, 躁熱減輕作, 一日發2-3次, 眠改善, 經來胸悶,心悸\n2025/0924 口腔潰瘍. 身濕\n2025/09/30 左胸刺痛感, 發作二次, 心跳快, 身濕不適, 淋巴結腫大變軟,\n2025/10/07 無刺痛, 無心悸, 夜間膚痛, ',NULL,NULL,NULL,'L239','過敏性接觸性皮膚炎，未明示原因',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,3541,0,0,0,0,NULL,NULL,0,0,3841,0,100,3841,3841,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-10-07 03:11:46');
