INSERT INTO `cases` VALUES (2776,1969,'陳柏諠','2025-10-07 11:37:46',NULL,'2025-10-07 11:49:25','2025-10-07 11:49:25','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,20,NULL,NULL,13,NULL,NULL,NULL,'林胤谷',NULL,NULL,'張介雪',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'乾癬復發, 臉, 頭皮, 腿皮膚紅斑塊, 睡不好, 胃脹不適, \n指甲乾癬\n2025/10/07 改善中, ',NULL,NULL,NULL,'L400','尋常性乾癬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'預約報到過號',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,4109,0,0,0,0,NULL,NULL,0,0,4409,0,100,4409,4409,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-10-07 04:31:14');
INSERT INTO `cases` VALUES (2777,659,'^劉聿程','2025-10-07 11:50:38',NULL,'2025-10-07 12:07:17','2025-10-07 12:07:17','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,21,NULL,NULL,14,NULL,NULL,NULL,'林胤谷',NULL,NULL,'張介雪',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'T主訴:全身皮膚紅斑塊加劇逾五年\n現病史:病患自述四肢、胸腹、腰背、面部、耳後、頭皮紅斑塊,皮膚色鮮紅,病灶邊缘明顯,皮膚增厚乾燥,鱗屑多,癢感稍微,以雙側腳掌及小腿尤甚,吃辣時加劇,水泡無,搔抓有滲組織液,指甲增厚與甲床剝離、點狀凹陷,關節活動正常 合併糖尿病,高血壓,HbA1c 6.5 sugar ac:110,高血壓服藥, \n2025/09/03 皮膚紅斑塊有屑. 近未改善\n2025/10/07 改善中,腿皮膚仍有紅斑塊',NULL,NULL,NULL,'L400','尋常性乾癬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'預約報到過號',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,14300,0,0,0,0,NULL,NULL,0,0,14600,0,100,14600,14600,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-10-07 04:30:23');
INSERT INTO `cases` VALUES (2778,1802,'莊泳沐','2025-10-08 13:44:46',NULL,'2025-10-08 13:54:37','2025-10-08 13:54:37','複診','內科','預約門診',NULL,'自費','普通疾病',NULL,'基層醫療','自費','申報','不申報','免卡',NULL,NULL,'午班','午班',1,NULL,1,NULL,NULL,1,NULL,NULL,NULL,'特約門診',NULL,NULL,'鄭雪菁',NULL,'特約門診',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'十年前, 手肘, 耳後皮膚乾紅斑塊, 皮膚炎四年前惡化, \n數月前泡湯後惡化, 現全身泛紅疹大片, \n杜必炎治療, 效不佳, 類固醇注射控制\n嚴重皮膚癢,睡不好, 水便,\n2025/09/16 後背退紅, 夜間癢減少, 淺眠, 睡不好, 腳趾痛風腫痛,  皮膚乾燥, 腳踝跟痛, 後背疔瘡\n2025/10/08 掌心紅,  手皮膚乾燥脫皮, 飲食不節, 手腕痛風作, 睡不好, ','91Kg',NULL,NULL,'L239','過敏性接觸性皮膚炎，未明示原因','I10','本態性(原發性)高血壓','M109','痛風',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,1500,8603,0,0,0,0,NULL,NULL,0,0,10103,0,100,10103,10103,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-10-08 06:28:35');
INSERT INTO `cases` VALUES (2779,9,'黃尉宸','2025-10-08 15:02:34',NULL,'2025-10-08 15:08:20','2025-10-08 15:08:20','複診','內科','一般門診',NULL,'自費','普通疾病','99','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'晚班','晚班',1,NULL,2,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:皮膚炎自出生6個月發作, \n現病史:皮膚炎自出生6個月發作, 初起於腳趾處皮膚乾裂,   皮膚炎發作於頭皮, 臉部, 頸部, 手肘, 手腕, 大小腿, 膝膕窩, 足踝, 腹腰背部,, 局部皮膚紅腫, 色鮮紅, 有搔抓傷口, , 西醫診斷為異位性皮膚炎, 曾使用西醫類固醇外用,  口服抗組織胺仍在使用,去年7月開始使用中藥外用。納可。二便平。容易鼻癢目癢耳癢。\n2025/09/10 青黛0, 腳背皮膚粗疹, 膕窩苔蘚化粗\n2025/10/08 ',NULL,NULL,NULL,'L2081','異位性神經皮膚炎',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,2440,0,0,0,0,NULL,NULL,0,0,2740,0,100,2740,2740,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-10-08 07:16:11');
