INSERT INTO `cases` VALUES (2808,596,'劉姿伶','2025-10-08 18:40:49',NULL,'2025-10-08 19:10:52','2025-10-08 19:10:52','複診','內科','預約門診',NULL,'自費','普通疾病',NULL,'基層醫療','自費','申報','不申報','免卡',NULL,NULL,'晚班','晚班',1,NULL,31,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'宋惠玲',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:皮膚紅疹、斑塊約1年多\n現病史:皮紅疹、斑塊约1年多。位於手掌、大腿、背部。色淡红。搔癢、些微脫皮。圓形居多。每次位置不固定。西醫診斷濕疹。曾使用治療:類固醇、抗組織胺。效果平。\n納可。排便2-3日1行質硬。眠因癢而差。易口乾。無泛酸、但飯後易腹脹。\n2025/09/22  腹部皮膚癢作,乾燥,  手臂皮膚粗疹癢, 膕窩小腿皮膚癢\n2025/10/08 唇炎, ',NULL,NULL,NULL,'L239','過敏性接觸性皮膚炎，未明示原因',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'預約報到過號',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,2950,0,0,0,0,NULL,NULL,0,0,3250,0,100,3250,3250,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-10-08 11:23:05');
