INSERT INTO `cases` VALUES (2871,256,'王國維','2025-10-14 08:54:56',NULL,'2025-10-14 09:05:48','2025-10-14 09:05:48','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,1,NULL,NULL,1,NULL,NULL,NULL,'林胤谷',NULL,NULL,'許梅卿',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:皮膚紅斑塊反覆约八年\n現病史:皮膚红AC斑塊反覆约八年,近一年加重,現額,手臂,後背和腿散布性紅斑塊有鳞屑,皮膚 會作,頭皮鳞属多,眠可,\n2025/07/30 臀部, 後背皮膚紅斑瑰 厚改善緩慢, ,手臂病灶作,頭皮病灶改善,红,屑少,有髮際邊緣, 高血脂飲食控制,  指甲病灶反覆,要載手套\n2025/10/14 皮膚紅斑塊變淡中,',NULL,NULL,NULL,'L400','尋常性乾癬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,6950,0,0,0,0,NULL,NULL,0,0,7250,0,100,7250,7250,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-10-14 01:13:23');
INSERT INTO `cases` VALUES (2872,1013,'吳峻次','2025-10-14 08:56:34',NULL,'2025-10-14 09:08:41','2025-10-14 09:08:41','複診','內科','一般門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,2,NULL,NULL,2,NULL,NULL,NULL,'林胤谷',NULL,NULL,'許梅卿',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:自國三起乾癣發作\n現病史:自國三起乾癬發作,現腹部和頭皮膚紅斑塊厚,大片,腳少許\n2025/05/27 腹部紅斑塊,早起變淡,後背皮膚新長病灶作減少,皮膚病灶泛紅,乾燥,頭皮膚發紅,乾燥屑多,毛囊炎腫痛,天熱流汗 近未作,體重110減至80多公斤,晚睡>11,,再次衛 教飲食\n2025/10/14 藥膏有顆粒',NULL,NULL,NULL,'L400','尋常性乾癬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,3742,0,0,0,0,NULL,NULL,0,0,4042,0,100,4042,4042,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-10-14 01:19:05');
INSERT INTO `cases` VALUES (2873,1313,'洪郁雯','2025-10-14 08:56:54',NULL,'2025-10-14 09:20:12','2025-10-14 09:20:12','複診','內科','預約門診',NULL,'自費','普通疾病',NULL,'基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,3,NULL,NULL,3,NULL,NULL,NULL,'林胤谷',NULL,NULL,'許梅卿',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'@全身皮膚乾燥, 粗, \n自幼濕疹作,類固醇治療, 反覆, 病灶滲液, 上胸熱,刺癢, ,壓迫處癢, 身熱嚴重, 大便硬改善,  \n2025/07/17 夜間癢, 擦複方苦蔘膏過敏, 昨夜癢, 無法入睡 , 用乾癬新M 07/17\n2025/07/29 入睡困難, 皮膚乾燥癢 明天白內障開刀\n皮膚擦油易有毛囊炎作, 左顳濕疹塊, 月經延後06/24.\n2025/08/12  睡眠改善, 腋下, 手肘皮膚痛稍減, 乾燥癢, , 08/10月經前腰痠,頭痛, 皮膚惡化. 08/18 月經來,7日,量減少, 經來腹部悶痛作\n2025/09/09 仍身熱,脖頸皮膚粗, 身躁熱,易流汗. 月2025/09/16 經09/09 至, 經量多三日, 頭暈, 偏頭痛作, 躁熱減輕作, 一日發2-3次, 眠改善, 經來胸悶,心悸\n2025/0924 口腔潰瘍. 身濕\n2025/09/30 左胸刺痛感, 發作二次, 心跳快, 身濕不適, 淋巴結腫大變軟,\n2025/10/07 無刺痛, 無心悸, 夜間膚痛,\n2025/10/14 腳底紅疹塊癢, 月經來頭痛, 躁熱濕悶減輕, 流鼻血, ',NULL,NULL,NULL,'L239','過敏性接觸性皮膚炎，未明示原因',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2013診所， 口服內用類固醇, 2024 /05 汗泡疹作,洗海鮮後發作, 2019 類固醇治療戒紅皮症作, \n血液ILIB, 未改善, 未用西藥治療, 惡化, 中醫密醫治療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,4435,0,0,0,0,NULL,NULL,0,0,4735,0,100,4735,4735,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-10-14 01:34:35');
