INSERT INTO `cases` VALUES (2883,112,'姚慧娟','2025-10-14 10:12:58',NULL,'2025-10-14 10:44:21','2025-10-14 10:44:21','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,12,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'許梅卿',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:皮膚鳞屑反覆\n現病史:乾癬41年,乾癬皮膚位手肘、小腿红斑大片,指甲剝離點藥改善,吃辛味皮膚復發,天冷皮膚作,頻尿改善,心血管危險因子抽血檢查.\n2025/07/08 左小腿有红斑塊红疹大片改善較少,冬天惡化,腿皮膚红斑塊增多。吃麻油雞,指甲病灶碰水加重 會痛 載手套,,癢搔抓暗褐,潮熱流汗反復,胃脹不適改善,指關節腫脹,\n2025/10/14 指甲乾癬,',NULL,NULL,NULL,'L409','乾癬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,2200,0,0,0,0,NULL,NULL,0,0,2500,0,100,2500,2500,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-10-14 02:54:05');
