INSERT INTO `cases` VALUES (2885,194,'馮美雲','2025-10-14 10:19:07',NULL,'2025-10-14 10:52:17','2025-10-14 10:52:17','複診','內科','預約門診',NULL,'自費','普通疾病',NULL,'基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,14,NULL,NULL,8,NULL,NULL,NULL,'林胤谷',NULL,NULL,'許梅卿',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:兩臉頰處紅斑1年\n現病史:患者1年前因不明原因兩臉頰出現紅斑,部分病灶處起丘疹,自覺緊繃感,偶有癢感,搔抓滲出組織液,偶爾眼睛周圍會癢。曾在皮膚科,懷疑是玫瑰疹使用外用藥膏metrenidazone治療後症狀改善,但仍偶有感,有壓力時症狀會較明顯。已停經。二便可。睡眠可。 Tchol:228,衛教\n 2025/08/05  暈眩改善, 手臂內側紅疹癢, 眼\n2025/09/09 眼皮跳動, 腿抽筋,\n2025/10/14 晨起, 打噴嚏,流鼻水',NULL,NULL,NULL,'L239','過敏性接觸性皮膚炎，未明示原因',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'預約報到過號',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,7440,0,0,0,0,NULL,NULL,0,0,7740,0,100,7740,7740,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-10-14 03:36:11');
