INSERT INTO `cases` VALUES (2893,2054,'洪長宏','2025-10-14 11:23:45',NULL,'2025-10-14 11:39:17','2025-10-14 11:39:17','複診','內科','預約門診',NULL,'自費','普通疾病','82','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,22,NULL,NULL,12,NULL,NULL,NULL,'林胤谷',NULL,NULL,'許梅卿',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'T  手肘, ,鼻, 眼, 耳, 癢, 膕窩,,胸乳癢\n頭皮癢,\n2025/09/23 後背皮膚泡疹作,單純泡疹, ? 一週,\n2025/09/30 後背皮膚紅疹減輕,\n2025/10./14  打噴嚏, 流鼻水, 眼癢, 膕窩癢搔抓仍',NULL,NULL,NULL,'J309','過敏性鼻炎','L239','過敏性接觸性皮膚炎，未明示原因',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'預約報到過號',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,1579,0,0,0,0,NULL,NULL,0,0,1879,0,100,1879,1879,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-10-14 04:12:41');
INSERT INTO `cases` VALUES (2894,141,'陳芝言','2025-10-14 11:38:24',NULL,'2025-10-14 11:44:17','2025-10-14 11:44:17','複診','內科','預約門診',NULL,'自費','普通疾病','99','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,23,NULL,NULL,13,NULL,NULL,NULL,'林胤谷',NULL,NULL,'許梅卿',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'2018/05/10\n主訴:全身皮膚紅疹片約四個月\n現病史:三個半月大起四肢關節處起红疹點與紅疹片,近來臉部 頸部及前胸紅疹加重,皮膚乾燥脫屑,嚴重時滲流組織液,天氣冷交替明顯時症加重, 目前臉部 頸部 上背部 手背腳背與四肢關節處有紅疹片伴隨脫屑 有輕微搔抓皮膚破損,四肢病灶明顯增厚,臉部大腿經常搔抓 擦西藥有減緩,半夜三點左右搔抓劇烈影響睡眠,近來外陰部處皮膚有發红,\n2025/10/14 ',NULL,NULL,NULL,'L309','皮膚炎','L209','異位性皮膚炎',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'預約報到過號',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,10682,0,0,0,0,NULL,NULL,0,0,10982,0,100,10982,10982,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-10-14 05:32:31');
