INSERT INTO `cases` VALUES (3030,520,'許惠華','2025-10-22 19:05:53',NULL,'2025-10-22 19:15:47','2025-10-22 19:15:47','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'晚班','晚班',1,NULL,20,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:乾癬多年,肘關節痛\n現病史:紅斑塊位頭皮,小腿,頭痛,睡眠不佳,頭痛作,胃泛酸   右小腿紅斑塊鲜红大片 中央病灶稍變淡,周仍鲜红作,,咽有痰減少,暗,少屑,左側少  LDL 208.Tchol 287,飲食血脂控制,衛教 潮熱有汗 頭痛頭脹 \n腿皮膚病灶紅腫會癢,\n2025/09/24 敷藥後改善, 更年期流汗,皮膚癢, 減少, 腿皮膚丘疹仍\n2025/10/22 ',NULL,NULL,NULL,'L400','尋常性乾癬','K219','胃食道逆性疾病未伴有食道炎',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'預約報到過號',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,1920,0,0,0,0,NULL,NULL,0,0,2220,0,100,2220,2220,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-10-22 11:17:48');
INSERT INTO `cases` VALUES (3031,578,'孫慶雲','2025-10-24 08:40:11',NULL,'2025-10-24 08:51:16','2025-10-24 08:51:16','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,1,NULL,NULL,3,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'2022/09/07\n主訴:皮膚紅斑塊二年\n現病史:乾癬發作二年以上,西藥治療,控制不佳,全身皮膚红斑塊遍布,指甲異常,體重下降,70->63kg,皮膚癢 \n睡不好 夜間皮膚乾燥搔癢搔抓減少作,,衛教戒菸,己戒菸,外出睡不好,則病灶加重,胃脹不適,胃脹,打嗝,飲食控制改善,頭皮病灶,陰部病灶癢,小腿皮膚 長紅疹搔抓傷口減少,鼻過敏,服西藥癢疹減,頭零星红斑塊,少運動,手指背搔抓红斑塊,衛教少搔抓\n2025/10/24 流鼻水, 打噴嚏',NULL,NULL,NULL,'L409','乾癬','J309','過敏性鼻炎',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,9356,0,0,0,0,NULL,NULL,0,0,9656,0,100,9656,9656,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-10-24 02:09:41');
