INSERT INTO `cases` VALUES (3054,775,'高寧希.','2025-10-25 08:20:55',NULL,'2025-10-25 08:24:04','2025-10-25 08:24:04','複診','內科','預約門診',NULL,'自費','普通疾病','99','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,3,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'宋惠玲',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'T 主訴:全身皮膚炎嚴重,泛紅有滲液\n現病史:全身皮膚炎發作自出生作,全身红红腫有滲液,頭皮膚臉乾燥有結痂 頭皮癢作 臉紅疹 手腕,腳踝粗,厚,小腿外側斑塊,蕁麻疹作,流鼻水,鼻塞,呼吸聲大,晨打噴嚏作, 眼周皮膚紅, 搔抓, 皮膚癢反覆\n2025/009/10   夜間搔抓手腕皮膚苔蘚化粗減輕,搔抓,減少 大腿皮膚红疹多改善,手肘病灶粗, 晨起流鼻水減少,打噴嚏作有改善,\n2025/10/25 改善多,',NULL,NULL,NULL,'L209','異位性皮膚炎',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,3600,0,0,0,0,NULL,NULL,0,0,3900,0,100,3900,3900,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-10-25 00:27:25');
