INSERT INTO `cases` VALUES (3096,133,'王丹穎','2025-10-27 14:50:25',NULL,'2025-10-27 15:02:11','2025-10-27 15:02:11','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'午班','晚班',1,NULL,1,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'張介雪',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:臉乾癬皮膚斑塊復發\n現病史:乾癬多年頭皮屑多,有厚斑塊,股溝皮膚有厚斑塊,額皮膚也有,胃酸逆流,眠不佳 焦慮,停服MTX臉皮膚紅斑作 手指異常,指甲惡化, 夜尿,胃泛酸作,乾咳\n2025/07/01  乾癬復發,臉皮膚紅斑塊 泛紅疹 肚臍疼痛作 服抗生素,胃泛酸,服西藥,飲食衛教 有改善,\n2025/10',NULL,NULL,NULL,'L400','尋常性乾癬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,2530,0,0,0,0,NULL,NULL,0,0,2830,0,100,2830,2830,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-10-27 07:08:15');
