INSERT INTO `cases` VALUES (3098,27,'徐若婷','2025-10-27 15:02:15',NULL,'2025-10-27 15:21:44','2025-10-27 15:21:44','複診','內科','預約門診',NULL,'自費','普通疾病','99','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'晚班','晚班',1,NULL,3,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'張介雪',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴: 四肢, 腰背牽連臀部泛發紅色搔癢丘疹超過五週\n現病史: 五週前四肢, 腰背牽連臀部突發性紅色搔癢丘疹, 無明確誘發因子/加重因子, 現病灶於四肢/手腳掌/手指腳趾與腰背/臀部, 以膝蓋最甚, 丘疹色紅且搔癢, 搔抓出血且滲組織液, 偶脫屑. 西醫診斷為濕疹, 塗抹類固醇可改善, 停藥後復發, 因癢甚影響睡眠. \n食慾可, 大便一天一行, 羊屎便, 小便可\n2025/10/27 ',NULL,NULL,NULL,'L209','異位性皮膚炎',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,2400,0,0,0,0,NULL,NULL,0,0,2700,0,100,2700,2700,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-10-27 07:33:03');
