INSERT INTO `cases` VALUES (3121,544,'余瑞珠.','2025-10-28 08:55:57',NULL,'2025-10-28 09:01:28','2025-10-28 09:01:28','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,1,NULL,NULL,1,NULL,NULL,NULL,'林胤谷',NULL,NULL,'游惠玲',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'T主訴:頭皮與皮膚斑塊反覆十多年\n病史:頭皮與皮膚斑塊,頭皮斑塊色淡紅稍有鱗屑,下肢斑塊色深紅帶明顯鱗屑。曾至台北市立聯合醫院昆明院區中醫科就診,療效不好。尚未至皮膚科就診(怕類固醇)。 \n眠差易醒,無胃悶胃食道逆流,無胸悶心悸,大便一日一行成條,無口乾渴。個性較急。\n2025/10/28 夜間口苦 ,夜間口乾 ,飲食不節,胃嘈雜 胃泛酸作 衛教飲食,有改善  小腿後側病灶紅斑塊結節,疤痕暗沉,,指甲乾癬作,天氣變化皮膚癢作,少有頭皮膚红斑塊, 壓力大,頭皮屑作,',NULL,NULL,NULL,'L409','乾癬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,3920,0,0,0,0,NULL,NULL,0,0,4220,0,100,4220,4220,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-10-28 06:48:15');
