INSERT INTO `cases` VALUES (3128,848,'薛晴安','2025-10-28 09:49:25',NULL,'2025-10-28 10:06:02','2025-10-28 10:06:02','複診','內科','預約門診',NULL,'自費','普通疾病','99','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,8,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'游惠玲',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'@主訴:皮膚搔癢自出生2個月發作\n現病史:皮膚炎自出生2個月發作,發作於臉部、耳後、頭部、上肢(手肘)、下肢(膝膕窩)、軀幹(腰背部右臀部、會陰),以臉部最為嚴重。局部皮膚红疹,色红,有搔抓滲出,皮膚乾燥,因癢甚夜眠差,睡眠中不自覺搔抓、不會醒來。曾使用西醫類固醇外用、口服抗組織胺和類固醇治療,鼻涕使用後症狀有改善,皮膚症狀有些微改善\n2025/10/28 father',NULL,NULL,NULL,'L209','異位性皮膚炎',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,8400,0,0,0,0,NULL,NULL,0,0,8700,0,100,8700,8700,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-10-28 02:13:54');
