INSERT INTO `cases` VALUES (3130,1012,'王瑩宏','2025-10-28 09:59:37',NULL,'2025-10-28 10:26:18','2025-10-28 10:26:18','複診','內科','一般門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,10,NULL,NULL,5,NULL,NULL,NULL,'林胤谷',NULL,NULL,'游惠玲',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'2019/01/14\n主訴:全身皮膚红斑塊反覆 逾4年\n現病史:病患自述皮膚红斑塊反覆逾4年,以大腿最為嚴重。病灶區色鲜紅,皮損邊缘明顯,有凸起、增厚、苔蘚化、脫屑、色素沈積、粗乾,指甲變形、增厚、甲床剝離、點狀凹陷, 。纳可,眠可,二便平。\n2025/07/09 手臂皮膚紅斑塊 右小腿红斑塊大片,乾燥有屑,左腿零星,頭皮屑多,衛教用藥方法,膝關節退化,膝腿皮開刀,後枕頭皮癢 腰腹部皮膚紅斑塊,指甲生長異常改善,胃痛,胃泛酸作飲食衛教,改善,偶發作,\n2025/9/10  近頭皮屑, 腿皮膚紅斑塊大片\n2025/10/28 藥粉太乾, ',NULL,NULL,NULL,'L400','尋常性乾癬','K3189','胃及十二指腸其他的疾病',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,3130,0,0,0,0,NULL,NULL,0,0,3430,0,100,3430,3430,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-10-28 02:37:13');
