INSERT INTO `cases` VALUES (3138,1313,'洪郁雯','2025-10-28 11:25:06',NULL,'2025-10-28 11:34:58','2025-10-28 11:34:58','複診','內科','一般門診',NULL,'自費','普通疾病',NULL,'基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,18,NULL,NULL,7,NULL,NULL,NULL,'林胤谷',NULL,NULL,'游惠玲',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'@全身皮膚乾燥, 粗, \n自幼濕疹作,類固醇治療, 反覆, 病灶滲液, 上胸熱,刺癢, ,壓迫處癢, 身熱嚴重, 大便硬改善,  \n2025/07/17 夜間癢, 擦複方苦蔘膏過敏, 昨夜癢, 無法入睡 , 用乾癬新M 07/17\n2025/07/29 入睡困難, 皮膚乾燥癢 明天白內障開刀\n皮膚擦油易有毛囊炎作, 左顳濕疹塊, 月經延後06/24.\n2025/08/12  睡眠改善, 腋下, 手肘皮膚痛稍減, 乾燥癢, , 08/10月經前腰痠,頭痛, 皮膚惡化. 08/18 月經來,7日,量減少, 經來腹部悶痛作\n2025/09/09 仍身熱,脖頸皮膚粗, 身躁熱,易流汗. 月2025/09/16 經09/09 至, 經量多三日, 頭暈, 偏頭痛作, 躁熱減輕作, 一日發2-3次, 眠改善, 經來胸悶,心悸\n2025/0924 口腔潰瘍. 身濕\n2025/09/30 左胸刺痛感, 發作二次, 心跳快, 身濕不適, 淋巴結腫大變軟,\n2025/10/07 無刺痛, 無心悸, 夜間膚痛,\n2025/10/14 腳底紅疹塊癢, 月經來頭痛, 躁熱濕悶減輕, 流鼻血,\n2025/10/21 近便秘羊屎便, 不順, 手,腳皮膚癢\n2025/10/28 臉皮膚脹痛感, 緊, 仍有身濕',NULL,NULL,NULL,'L239','過敏性接觸性皮膚炎，未明示原因',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,4905,0,0,0,0,NULL,NULL,0,0,5205,0,100,5205,5205,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-10-28 03:55:25');
INSERT INTO `cases` VALUES (3140,1802,'莊泳沐','2025-10-28 14:47:54',NULL,'2025-10-28 14:57:38','2025-10-28 14:57:38','複診','內科','預約門診',NULL,'自費','普通疾病','02','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'午班','午班',1,NULL,20,NULL,NULL,9,NULL,NULL,NULL,'特約門診',NULL,NULL,'張介雪',NULL,'特約門診',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'十年前, 手肘, 耳後皮膚乾紅斑塊, 皮膚炎四年前惡化, \n數月前泡湯後惡化, 現全身泛紅疹大片, 杜必炎治療, 效不佳, 類固醇注射控制 , 嚴重皮膚癢,睡不好, 水便,\n2025/09/16 後背退紅, 夜間癢減少, 淺眠, 睡不好, 腳趾痛風腫痛,  皮膚乾燥, 腳踝跟痛, 後背疔瘡\n2025/10/22  掌心紅減輕,  手皮膚乾燥脫皮, 乾燥癢作飲食不節, 手腕痛風作, 睡不好,近咽痛, 不適, 目前配合照光, 診所打抗敏針, 每週治療\n2025/10/28 左踝紅腫作, 痛風','91Kg','mites allergy',NULL,'L239','過敏性接觸性皮膚炎，未明示原因','I10','本態性(原發性)高血壓','M109','痛風',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,1500,9157,0,0,0,0,NULL,NULL,0,0,10657,0,100,10657,10657,NULL,NULL,'現金','現金',NULL,'True','False','True','False','False','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-10-28 07:26:11');
