INSERT INTO `cases` VALUES (3193,196,'胡寧遠','2025-11-04 09:52:36',NULL,'2025-11-04 09:55:34','2025-11-04 09:55:34','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,10,NULL,NULL,5,NULL,NULL,NULL,'林胤谷',NULL,NULL,'張介雪',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:红斑塊位頭皮,肩,臂,腿\n現病史:乾癬20年以上,目前紅斑塊全身零星分布,指甲生長異常,腰痛,皮膚,胃嘈雜,\n2025/07/22 臉皮膚泛红.有屑 眉間,鼻側皮膚泛紅,乾燥,天冷皮膚乾燥,胃泛酸 胃嘈雜 飲食衛教後,後腰部红斑塊中間病灶變平,指導冰敷包敷,衛教用藥,腰痛 未作,\n2025/11/04 後腰紅斑塊大片, 厚',NULL,NULL,NULL,'L400','尋常性乾癬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'預約報到過號',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,3314,0,0,0,0,NULL,NULL,0,0,3614,0,100,3614,3614,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-11-04 02:32:17');
