INSERT INTO `cases` VALUES (3195,397,'洪怡瑩','2025-11-04 10:21:56',NULL,'2025-11-04 10:29:29','2025-11-04 10:29:29','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,12,NULL,NULL,7,NULL,NULL,NULL,'林胤谷',NULL,NULL,'張介雪',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'@ 主訴:全身皮膚零星紅斑塊三年\n現病史:乾癬發作三年,臉和臀部病灶癢,頭皮後枕癢,四肢零星,大腿病灶大片,陰部也有,易醒,月經來嚴重經痛,皮膚乾癬,治療改善中,鳞屑減少, 易醒改善\n2025/05/07掉髮多,腳趾乾癬作,後背病灶 頭部皮癢作,腿皮膚红斑塊近惡化,手肘外斑塊改善,月經不規則經痛輕微,衛教運動舒壓\n2025/09/03 經痛一日, 今日經來,未痛, 緊張皮膚癢搔抓\n2025/11/04經痛1減輕, 右小腿皮膚斑塊改善. 咳嗽數日, ',NULL,NULL,NULL,'L409','乾癬','F410','特定場所畏懼症的恐慌症',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'預約報到過號',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,5983,0,0,0,0,NULL,NULL,0,0,6283,0,100,6283,6283,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-11-04 02:56:42');
