INSERT INTO `cases` VALUES (3253,1935,'卓彥君','2025-11-08 08:16:04',NULL,'2025-11-08 08:46:55','2025-11-08 08:46:55','複診','內科','預約門診',NULL,'自費','普通疾病',NULL,'基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,6,NULL,NULL,5,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'嬰兒時期異膚, 氣喘 \n手部汗泡疹發作二年以上, \n今年惡化, 口周, 耳, 脖頸皮膚炎紅腫, 手指皮膚乾燥, 脫屑,\n2025/09/06 紅腫,脫屑減輕, \n2025/10/11 持續改善, 手部乾粗\n2025/10/25 手指甲溝炎仍有, 乾燥, 己無紅腫,偶打噴嚏作\n2025/11/07手指皮膚乾燥, 粗, ',NULL,NULL,NULL,'L239','過敏性接觸性皮膚炎，未明示原因',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,2303,0,0,0,0,NULL,NULL,0,0,2603,0,100,2603,2603,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-11-08 01:08:51');
INSERT INTO `cases` VALUES (3254,333,'李宗哲','2025-11-08 08:29:27',NULL,'2025-11-08 08:52:50','2025-11-08 08:52:50','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,7,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'@主訴:乾癬十多年\n現病史:全身皮膚泛紅,紅斑塊遍布,乾燥,會癢,腿和背背斑塊多\n2025/07/07  腹部紅斑塊大片, 手臂前臂皮膚紅斑塊 ,上臂較多, 未量血壓,建議控制體重,飲食,小腿皮膚乾燥,病灶有屑減少,上半身乾癬紅斑塊大片,\n2025/09/06 後背, 胸腹紅斑塊大片,\n2025/11/07 有改善,',NULL,NULL,NULL,'L409','乾癬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,5600,0,0,0,0,NULL,NULL,0,0,5900,0,100,5900,5900,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-11-08 01:05:50');
