INSERT INTO `cases` VALUES (3316,206,'陳勻晞','2025-11-11 10:33:08',NULL,'2025-11-11 10:36:55','2025-11-11 10:36:55','複診','內科','一般門診',NULL,'自費','普通疾病','99','三歲兒童','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,8,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'范詩豔',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:頭皮臉紅疹粗\n現病史:頭皮膚搔抓泛紅,臉頰乾粗,四肢零星,頭皮癢搔抓反復,下巴磨擦\n2025/08/22 眼角皮膚炎 紅疹己無,,臉皮膚乾燥,改善 少有搔抓作,擦藥,皮膚乾燥減輕,衛教\n2025/11/11 近蕁麻疹作,臉乾燥癢',NULL,NULL,NULL,'L209','異位性皮膚炎',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,1740,0,0,0,0,NULL,NULL,0,0,2040,0,100,2040,2040,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-11-11 03:04:43');
INSERT INTO `cases` VALUES (3317,1313,'洪郁雯','2025-11-11 10:36:31',NULL,'2025-11-11 10:44:43','2025-11-11 10:44:43','複診','內科','預約門診',NULL,'自費','普通疾病',NULL,'基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,9,NULL,NULL,3,NULL,NULL,NULL,'林胤谷',NULL,NULL,'范詩豔',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'@全身皮膚乾燥, 粗, \n自幼濕疹作,類固醇治療, 反覆, 病灶滲液, 上胸熱,刺癢, ,壓迫處癢, 身熱嚴重, 大便硬改善,  \n2025/07/17 夜間癢, 擦複方苦蔘膏過敏, 昨夜癢, 無法入睡 , 用乾癬新M 07/17\n2025/07/29 入睡困難, 皮膚乾燥癢 明天白內障開刀\n皮膚擦油易有毛囊炎作, 左顳濕疹塊, 月經延後06/24.\n2025/08/12  睡眠改善, 腋下, 手肘皮膚痛稍減, 乾燥癢, , 08/10月經前腰痠,頭痛, 皮膚惡化. 08/18 月經來,7日,量減少, 經來腹部悶痛作\n2025/09/09 仍身熱,脖頸皮膚粗, 身躁熱,易流汗. 月2025/09/16 經09/09 至, 經量多三日, 頭暈, 偏頭痛作, 躁熱減輕作, 一日發2-3次, 眠改善, 經來胸悶,心悸\n2025/0924 口腔潰瘍. 身濕\n2025/09/30 左胸刺痛感, 發作二次, 心跳快, 身濕不適, 淋巴結腫大變軟,\n2025/10/07 無刺痛, 無心悸, 夜間膚痛,\n2025/10/14 腳底紅疹塊癢, 月經來頭痛, 躁熱濕悶減輕, 流鼻血,\n2025/10/21 近便秘羊屎便, 不順, 手,腳皮膚癢\n2025/10/28 臉皮膚脹痛感, 緊, 仍有身濕\n2025/11/04 近臉皮膚紅腫,乾燥, 手水腫三天,. 皮膚熱, 緊,\n2025/11/11 月經來, 頭痛作, 皮膚乾燥, ',NULL,NULL,NULL,'L239','過敏性接觸性皮膚炎，未明示原因',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'預約報到過號',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,5255,0,0,0,0,NULL,NULL,0,0,5555,0,100,5555,5555,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-11-11 03:50:43');
INSERT INTO `cases` VALUES (3318,578,'孫慶雲','2025-11-11 10:52:57',NULL,'2025-11-11 11:08:56','2025-11-11 11:08:56','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,10,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'范詩豔',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'2022/09/07\n主訴:皮膚紅斑塊二年\n現病史:乾癬發作二年以上,西藥治療,控制不佳,全身皮膚红斑塊遍布,指甲異常,體重下降,70->63kg,皮膚癢 \n睡不好 夜間皮膚乾燥搔癢搔抓減少作,,衛教戒菸,己戒菸,外出睡不好,則病灶加重,胃脹不適,胃脹,打嗝,飲食控制改善,頭皮病灶,陰部病灶癢,小腿皮膚 長紅疹搔抓傷口減少,鼻過敏,服西藥癢疹減,頭零星红斑塊,少運動,手指背搔抓红斑塊,衛教少搔抓\n2025/10/24 流鼻水, 打噴嚏\n2025/11/11 擦複方青黛M, 不適, 改善複方青香9PC',NULL,NULL,NULL,'L409','乾癬','J309','過敏性鼻炎',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,0,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,4500,0,0,0,0,NULL,NULL,0,0,4800,4800,100,0,0,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-11-11 03:50:49');
