INSERT INTO `cases` VALUES (3338,1027,'危妍潔','2025-11-12 18:39:13',NULL,'2025-11-12 19:13:12','2025-11-12 19:13:12','複診','內科','預約門診',NULL,'自費','普通疾病',NULL,'基層醫療','自費','申報','不申報','免卡',NULL,NULL,'晚班','晚班',1,NULL,15,NULL,NULL,7,NULL,NULL,NULL,'林胤谷',NULL,NULL,'鄭雪菁',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:手肘內皮膚癢搔抓\n現病史:手肘皮膚乾燥,暗沈癢搔抓,手指皮膚泛红乾燥,腳足背,後頸也有,眼癢,流鼻水反復\n2025/06/19 ,腹部皮膚癢暗沈, ,大腿內側皮膚紅疹搔抓\n2025/07/31 四肢屈側皮膚癢,本週惡化\n2025/08/21 本週改善. 腿皮膚魚鱗乾燥\n2025/09/11 腿皮膚變稍光滑\n2025/10/22 肘內皮膚炎紅己無, 仍乾,\n2025/11/12 皮膚微乾, 流鼻水, 鼻塞, ',NULL,NULL,NULL,'L239','過敏性接觸性皮膚炎，未明示原因',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'預約報到過號',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,1922,0,0,0,0,NULL,NULL,0,0,2222,0,100,2222,2222,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-11-12 11:33:58');
