INSERT INTO `cases` VALUES (3360,438,'林媚鈴','2025-11-15 08:37:37',NULL,'2025-11-15 09:02:25','2025-11-15 09:02:25','複診','內科','預約門診',NULL,'自費','普通疾病','28','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,7,NULL,NULL,6,NULL,NULL,NULL,'林胤谷',NULL,NULL,'許梅卿',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'主訴:乾癬復發\n現病史:乾癬接受藥物及照光治療. 全身皮膚乾,近乾復發,手指皮膚乾粗,頭皮病灶,關節脹,胃脹不適,大便可,手指甲剝離,\n2025/08/30  頭皮膚乾癬紅有屑, 手臂皮膚病灶 少红疹,手關節腫 脹 減輕, 皮膚紅斑塊, ,胃脹少作\n2025/09/27 改善中, 頭皮膚癢, 吃月餅, 關節痛,\n2025/11/15  關節緊痛改善, 腫減輕, 手皮膚乾燥癢,',NULL,NULL,NULL,'L400','尋常性乾癬','K279','消化性潰瘍，部位未明示，未明示急性或慢性，未伴有出血或穿孔',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,2723,0,0,0,0,NULL,NULL,0,0,3023,0,100,3023,3023,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-11-15 01:42:48');
