INSERT INTO `cases` VALUES (3439,2385,'涂姝婷','2025-11-18 10:33:44',NULL,'2025-11-18 10:59:40','2025-11-18 10:59:40','初診','內科','預約門診',NULL,'自費','普通疾病','99','基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,10,NULL,NULL,NULL,NULL,NULL,NULL,'林胤谷',NULL,NULL,'范詩豔',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'腳底汗泡疹作, 手指皮膚乾燥, ',NULL,NULL,NULL,'L209','異位性皮膚炎',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,240,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,500,1570,0,0,0,0,NULL,NULL,0,0,2070,0,100,2070,2070,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-11-18 03:06:44');
INSERT INTO `cases` VALUES (3440,1313,'洪郁雯','2025-11-18 10:40:55',NULL,'2025-11-18 11:05:04','2025-11-18 11:05:04','複診','內科','預約門診',NULL,'自費','普通疾病',NULL,'基層醫療','自費','申報','不申報','免卡',NULL,NULL,'早班','早班',1,NULL,11,NULL,NULL,5,NULL,NULL,NULL,'林胤谷',NULL,NULL,'范詩豔',NULL,'林胤谷',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL,'@全身皮膚乾燥, 粗, \n自幼濕疹作,類固醇治療, 反覆, 病灶滲液, 上胸熱,刺癢, ,壓迫處癢, 身熱嚴重, 大便硬改善,  \n2025/07/17 夜間癢, 擦複方苦蔘膏過敏, 昨夜癢, 無法入睡 , 用乾癬新M 07/17\n2025/07/29 入睡困難, 皮膚乾燥癢 明天白內障開刀\n皮膚擦油易有毛囊炎作, 左顳濕疹塊, 月經延後06/24.\n2025/08/12  睡眠改善, 腋下, 手肘皮膚痛稍減, 乾燥癢, , 08/10月經前腰痠,頭痛, 皮膚惡化. 08/18 月經來,7日,量減少, 經來腹部悶痛作\n2025/09/09 仍身熱,脖頸皮膚粗, 身躁熱,易流汗. 月2025/09/16 經09/09 至, 經量多三日, 頭暈, 偏頭痛作, 躁熱減輕作, 一日發2-3次, 眠改善, 經來胸悶,心悸\n2025/0924 口腔潰瘍. 身濕\n2025/09/30 左胸刺痛感, 發作二次, 心跳快, 身濕不適, 淋巴結腫大變軟,\n2025/10/07 無刺痛, 無心悸, 夜間膚痛,\n2025/10/14 腳底紅疹塊癢, 月經來頭痛, 躁熱濕悶減輕, 流鼻血,\n2025/10/21 近便秘羊屎便, 不順, 手,腳皮膚癢\n2025/10/28 臉皮膚脹痛感, 緊, 仍有身濕\n2025/11/04 近臉皮膚紅腫,乾燥, 手水腫三天,. 皮膚熱, 緊,\n2025/11/11 月經來, 頭痛作, 皮膚乾燥,\n2025/11/18 感冒, 服前方易燥熱',NULL,NULL,NULL,'L239','過敏性接觸性皮膚炎，未明示原因',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'False','False','False','False','False','False','False','False',NULL,NULL,NULL,200,0,0,0,0,0,0,0,0,NULL,0,NULL,0,0,0,0,NULL,0,300,3317,0,0,0,0,NULL,NULL,0,0,3617,0,100,3617,3617,NULL,NULL,'現金','現金',NULL,'True','False','True','True','True','False','False','False',NULL,NULL,NULL,'<DOCUMENT content=\"cshis\"><treat_data><registered_date/><seq_number/><clinic_id/><security_signature/><sam_id/><register_duplicated/><upload_time/><upload_type>1</upload_type><treat_after_check>1</treat_after_check><prescript_sign_time/><identification/></treat_data></DOCUMENT>',NULL,'2025-11-18 03:32:26');
